const SF_LANGS = { en: 0, es: 1, de: 2 };
// Langue de HA (profil de l'utilisateur) ; langue non gérée -> anglais.
function sfLang(hass) {
  const l = String((hass && ((hass.locale && hass.locale.language) || hass.language)) || "en").slice(0, 2).toLowerCase();
  return l === "fr" || l in SF_LANGS ? l : "en";
}
function sfTr(lang, key, vars) {
  let s = key;
  if (lang !== "fr") { const e = SF_T[key]; if (e) s = e[SF_LANGS[lang] ?? 0]; }
  return vars ? s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? "")) : s;
}

const SF_C = {
  cyan: "#00e5ff", amber: "#ffb300", red: "#ff3355", green: "#2bff88",
  grey: "#5b6b7d", text: "#cfefff", dim: "#7fa3bd",
};

const SF_CSS = `
  :host { display:block; }
  .hud { position:relative; overflow:hidden; border-radius:14px; padding:16px 18px 18px;
    background: radial-gradient(ellipse at 50% -20%, #0d2440 0%, #06101d 60%, #03080f 100%);
    border:1px solid rgba(0,229,255,.22); color:${SF_C.text};
    font-family:'B612 Mono', ui-monospace, monospace; font-size:13px;
    box-shadow: inset 0 0 40px rgba(0,229,255,.06), 0 0 22px rgba(0,229,255,.07); }
  .hud::after { content:""; position:absolute; inset:0; pointer-events:none;
    background: repeating-linear-gradient(0deg, rgba(255,255,255,.022) 0 1px, transparent 1px 3px); }
  .c { position:absolute; width:14px; height:14px; border-color:${SF_C.cyan}; border-style:solid; opacity:.8; }
  .c.tl { top:6px; left:6px; border-width:2px 0 0 2px; } .c.tr { top:6px; right:6px; border-width:2px 2px 0 0; }
  .c.bl { bottom:6px; left:6px; border-width:0 0 2px 2px; } .c.br { bottom:6px; right:6px; border-width:0 2px 2px 0; }
  .head { display:flex; align-items:center; gap:10px; margin-bottom:14px;
    font-family:Orbitron, sans-serif; font-weight:700; font-size:12px; letter-spacing:.22em;
    text-transform:uppercase; color:${SF_C.cyan}; text-shadow:0 0 8px rgba(0,229,255,.6); }
  .head .sub { margin-left:auto; font-family:'B612 Mono',monospace; font-weight:400;
    letter-spacing:.08em; font-size:10px; color:${SF_C.dim}; text-shadow:none; }
  .dot { width:8px; height:8px; border-radius:50%; background:${SF_C.cyan};
    box-shadow:0 0 8px ${SF_C.cyan}; animation: blink 1.6s infinite; }
  @keyframes blink { 50% { opacity:.25; } }
  .click { cursor:pointer; }
  .click:hover { filter:brightness(1.25); }
  .muted { color:${SF_C.grey}; }
  .lbl { font-size:10px; letter-spacing:.14em; text-transform:uppercase; color:${SF_C.dim}; }
  .val { font-family:Orbitron, sans-serif; font-weight:500; }
  [data-call] { cursor:pointer; user-select:none; -webkit-tap-highlight-color:transparent;
    transition: transform .12s, box-shadow .2s, background .2s, border-color .2s, color .2s; }
  [data-call]:active { transform:scale(.95); }
  [data-call].sent { box-shadow:0 0 0 2px ${SF_C.cyan}, 0 0 18px rgba(0,229,255,.7) !important; }
  [data-call].fail { box-shadow:0 0 0 2px ${SF_C.red}, 0 0 18px rgba(255,51,85,.7) !important; }
  [data-call].armed { border-color:${SF_C.amber} !important; color:${SF_C.amber} !important;
    background:rgba(255,179,0,.14) !important; animation: blink .5s infinite; }
  .btn { display:inline-flex; align-items:center; justify-content:center; gap:6px; padding:7px 11px;
    border-radius:8px; border:1px solid rgba(0,229,255,.25); background:rgba(0,229,255,.05);
    color:${SF_C.text}; font-family:'B612 Mono',monospace; font-size:11px; letter-spacing:.06em; }
  .btn:hover { border-color:${SF_C.cyan}; color:#fff; }
  .btn.on { border-color:${SF_C.cyan}; background:rgba(0,229,255,.18); color:#fff;
    box-shadow: inset 0 0 12px rgba(0,229,255,.25), 0 0 10px rgba(0,229,255,.25); }
  .seg { display:flex; flex-wrap:wrap; gap:6px; }
`;

class SfBase extends HTMLElement {
  setConfig(config) {
    if (!config) throw new Error(`${this.localName} : config requise`);
    this._config = this.defaults ? { ...this.defaults(), ...config } : config;
    if (!this.shadowRoot) this.attachShadow({ mode: "open" });
    this._dirty = true;
    this._schedule();
  }
  set hass(hass) {
    this._hass = hass;
    this._schedule();
  }
  _schedule() {
    if (this._raf || !this._hass || !this._config) return;
    this._raf = requestAnimationFrame(() => {
      this._raf = null;
      // HA rappelle `hass` à chaque changement d'état de toute la maison : on ne
      // réécrit le DOM que si le rendu a réellement changé, sinon les animations
      // (rotations 3D, flux) repartiraient de zéro plusieurs fois par seconde.
      const html = `<style>${SF_CSS}${this.css ? this.css() : ""}</style>${this.render()}`;
      if (html === this._lastHtml) return;
      this._lastHtml = html;
      this.shadowRoot.innerHTML = html;
      this.shadowRoot.querySelectorAll("[data-e]").forEach((el) =>
        el.addEventListener("click", (ev) => { ev.stopPropagation(); this._moreInfo(el.dataset.e); }));
      this.shadowRoot.querySelectorAll("[data-call]").forEach((el) =>
        el.addEventListener("click", (ev) => { ev.stopPropagation(); this._onCall(el); }));
      if (this.afterRender) this.afterRender();
    });
  }
  /*
   * Pilotage : un élément `data-call="domaine.service"` + `data-d='{json}'` appelle le
   * service au clic. Avec `data-confirm="texte"`, il faut deux appuis en moins de 4 s
   * (le premier arme le bouton et affiche le texte) : réservé aux actions lourdes.
   */
  _onCall(el) {
    if (el.dataset.confirm && !el.classList.contains("armed")) {
      el.classList.add("armed");
      el.dataset.label = el.innerHTML;
      el.innerHTML = this.esc(el.dataset.confirm);
      setTimeout(() => { if (el.isConnected && el.classList.contains("armed")) { el.classList.remove("armed"); el.innerHTML = el.dataset.label; } }, 4000);
      return;
    }
    if (el.classList.contains("armed")) { el.classList.remove("armed"); el.innerHTML = el.dataset.label; }
    const [domain, service] = el.dataset.call.split(".");
    let data = {};
    try { data = el.dataset.d ? JSON.parse(el.dataset.d) : {}; } catch (e) { return; }
    el.classList.add("sent");
    setTimeout(() => el.classList.remove("sent"), 600);
    this._hass.callService(domain, service, data).catch((err) => {
      el.classList.add("fail");
      el.title = String(err && err.message || err);
      setTimeout(() => el.classList.remove("fail"), 2500);
    });
  }
  // Attributs d'un bouton de pilotage, à insérer dans une balise.
  call(service, data, confirm) {
    return `data-call="${service}" data-d="${this.esc(JSON.stringify(data || {}))}"${confirm ? ` data-confirm="${this.esc(confirm)}"` : ""}`;
  }
  // Basculer une entité selon son domaine (script : lancer).
  toggleCall(id) {
    const d = (id || "").split(".")[0];
    if (d === "script") return this.call("script.turn_on", { entity_id: id });
    if (d === "scene") return this.call("scene.turn_on", { entity_id: id });
    if (d === "button") return this.call("button.press", { entity_id: id });
    return this.call(["light", "switch", "fan", "input_boolean", "automation"].includes(d) ? `${d}.toggle` : "homeassistant.toggle", { entity_id: id });
  }
  isOn(id) { const s = this.st(id); return !!s && ["on", "open", "home", "playing", "cleaning", "heat", "cool", "dry", "fan_only", "heat_cool"].includes(s.state); }
  // Puissance en W quelle que soit l'unité déclarée (certains compteurs publient en kW).
  watts(id) {
    const n = this.num(id); if (n === null) return null;
    const u = this.unit(id).toLowerCase();
    return u === "kw" ? n * 1000 : u === "mw" ? n * 1e6 : n;
  }
  kw(w) { return w === null ? "—" : Math.abs(w) >= 1000 ? `${(w / 1000).toFixed(2)} kW` : `${Math.round(w)} W`; }
  icon(name, size = 20, color) { return `<ha-icon icon="${this.esc(name)}" style="--mdc-icon-size:${size}px${color ? `;color:${color}` : ""}"></ha-icon>`; }
  _moreInfo(entityId) {
    const ev = new Event("hass-more-info", { bubbles: true, composed: true });
    ev.detail = { entityId };
    this.dispatchEvent(ev);
  }
  // Les états viennent parfois d'API externes (car manufacturers' clouds, Frigate…) : tout texte dynamique
  // passe par esc() avant d'être injecté dans le HTML.
  esc(v) {
    return String(v ?? "").replace(/[&<>"']/g, (ch) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
  }
  st(id) { return id && this._hass ? this._hass.states[id] : undefined; }
  ok(id) { const s = this.st(id); return !!s && !["unknown", "unavailable"].includes(s.state); }
  num(id) { if (!this.ok(id)) return null; const n = parseFloat(this.st(id).state); return isNaN(n) ? null : n; }
  unit(id) { const s = this.st(id); return (s && s.attributes.unit_of_measurement) || ""; }
  fmt(id, digits = 0) {
    const n = this.num(id);
    if (n === null) return this.ok(id) ? this.esc(this.st(id).state) : "—";
    return `${n.toFixed(digits)}`;
  }
  get lang() { return sfLang(this._hass); }
  get loc() { const h = this._hass; return (h && ((h.locale && h.locale.language) || h.language)) || "en"; }
  t(key, vars) { return sfTr(this.lang, key, vars); }
  ago(id) {
    const s = this.st(id); if (!s) return "";
    const m = Math.round((Date.now() - new Date(s.last_changed).getTime()) / 60000);
    if (m < 1) return this.t("à l'instant"); if (m < 60) return this.t("il y a {n} min", { n: m });
    const h = Math.round(m / 60); return h < 48 ? this.t("il y a {n} h", { n: h }) : this.t("il y a {n} j", { n: Math.round(h / 24) });
  }
  frame(title, sub, body, extraClass = "") {
    return `<div class="hud ${extraClass}"><i class="c tl"></i><i class="c tr"></i><i class="c bl"></i><i class="c br"></i>
      <div class="head"><span class="dot"></span>${title}<span class="sub">${sub || ""}</span></div>${body}</div>`;
  }
  // Minuteur d'un bouton (ex. sèche-serviette) : { actif, reste (min) }. Un rafraîchissement
  // toutes les 20 s tant qu'un minuteur tourne, sinon le décompte resterait figé entre deux changements d'état.
  timerInfo(id) {
    const t = id && this.st(id);
    if (!t || t.state !== "active") return { actif: false, reste: 0 };
    if (!this._ti) this._ti = setInterval(() => this._schedule(), 20000);
    const fin = Date.parse(t.attributes.finishes_at);
    return { actif: true, reste: isNaN(fin) ? null : Math.max(1, Math.ceil((fin - Date.now()) / 60000)) };
  }
  disconnectedCallback() { if (this._ti) { clearInterval(this._ti); this._ti = null; } }
  getCardSize() { return 4; }
}

/* ------------------------------------------------------------------ ALERTE */
/*
 * type: custom:sf-alert-card
 * alarm: alarm_control_panel.x
 * ring: binary_sensor.x            # sonnette
 * snapshot: camera.x               # photo affichée en cas de sonnette
 * leaks: [binary_sensor.x, ...]    # fuites
 * doors: [binary_sensor.x, ...]    # ouvertures (informatif)
 * power: sensor.x                 # tension d'entrée onduleur ; alerte si < power_below (200 V)
 * hide_sim: true                  # masque le bouton de simulation
 */
class SfAlertCard extends SfBase {
  defaults() { return { leaks: [], doors: [] }; }
  css() {
    return `
      .alert .hud, .hud.alert { border-color:rgba(255,51,85,.7);
        background: radial-gradient(ellipse at 50% 0%, #4a0714 0%, #1a0308 65%, #0a0104 100%);
        animation: pulse 1.1s infinite; }
      .hud.alert .c { border-color:${SF_C.red}; }
      .hud.alert .head { color:${SF_C.red}; text-shadow:0 0 10px rgba(255,51,85,.8); }
      .hud.alert .dot { background:${SF_C.red}; box-shadow:0 0 10px ${SF_C.red}; animation-duration:.6s; }
      @keyframes pulse { 50% { box-shadow: inset 0 0 60px rgba(255,51,85,.35), 0 0 30px rgba(255,51,85,.45); } }
      .big { font-family:Orbitron,sans-serif; font-weight:700; font-size:26px; letter-spacing:.08em;
        color:#fff; text-shadow:0 0 14px rgba(255,51,85,.9); margin:4px 0 10px; }
      .snap { width:100%; border-radius:10px; border:1px solid rgba(255,51,85,.6); display:block; margin-top:6px; }
      .calm { display:flex; align-items:center; gap:18px; flex-wrap:wrap; }
      .calm .state { font-family:Orbitron,sans-serif; font-size:18px; color:${SF_C.green};
        text-shadow:0 0 10px rgba(43,255,136,.6); letter-spacing:.1em; }
      .chips { display:flex; flex-wrap:wrap; gap:6px; margin-top:12px; }
      .chip::before { content:""; display:inline-block; width:6px; height:6px; border-radius:50%; background:currentColor; margin-right:6px; vertical-align:1px; }
      .chip.leak::before { border-radius:50% 50% 50% 0; transform:rotate(-45deg); }
      .chip { padding:4px 9px; border-radius:20px; font-size:10px; letter-spacing:.08em;
        border:1px solid rgba(0,229,255,.25); background:rgba(0,229,255,.05); }
      .chip.on { border-color:${SF_C.red}; color:${SF_C.red}; background:rgba(255,51,85,.1); }
      .chip.mute { border-color:${SF_C.amber}; color:${SF_C.amber}; background:rgba(255,179,0,.08); }
      .chip.ok { color:${SF_C.green}; border-color:rgba(43,255,136,.35); }
      .sim { margin-left:auto; background:none; border:1px solid rgba(0,229,255,.35); color:${SF_C.dim};
        font-family:'B612 Mono',monospace; font-size:10px; letter-spacing:.1em; padding:5px 10px;
        border-radius:6px; cursor:pointer; }
      .sim:hover { color:${SF_C.cyan}; border-color:${SF_C.cyan}; }`;
  }
  _name(id) { const s = this.st(id); return this.esc((s && s.attributes.friendly_name) || id); }
  render() {
    const c = this._config;
    const sim = this._simUntil && Date.now() < this._simUntil;
    const ring = sim || (this.st(c.ring) && this.st(c.ring).state === "on");
    const alarmS = this.st(c.alarm);
    const alarmTriggered = alarmS && alarmS.state === "triggered";
    const leaksOn = c.leaks.filter((id) => this.st(id) && this.st(id).state === "on");
    const pw = c.power ? this.st(c.power) : null;
    const pwv = c.power ? this.num(c.power) : null;
    const powerCut = pwv !== null && pwv < (c.power_below ?? 200);
    const mute = [...c.leaks, c.ring, c.alarm].filter((id) => id && !this.ok(id));

    if (ring || alarmTriggered || leaksOn.length || powerCut) {
      let title = this.t("ALERTE"), what = "";
      if (powerCut) { title = this.t("COUPURE DE COURANT"); what = this.t("Plus de tension en entrée de l'onduleur"); }
      if (leaksOn.length) { title = this.t("FUITE D'EAU"); what = leaksOn.map((i) => this._name(i)).join(" · "); }
      if (alarmTriggered) { title = this.t("INTRUSION"); what = this.t("Alarme déclenchée"); }
      if (ring) { title = this.t("SONNETTE"); what = sim ? this.t("simulation locale — rien n'est envoyé")
        : this.t("à {t}", { t: new Date(this.st(c.ring).last_changed).toLocaleTimeString(this.loc, { hour: "2-digit", minute: "2-digit" }) }); }
      const snapState = this.st(c.snapshot);
      const img = ring && snapState && snapState.attributes.entity_picture
        ? `<img class="snap click" data-e="${c.snapshot}" src="${this.esc(snapState.attributes.entity_picture)}">` : "";
      return this.frame(this.t("Alerte"), new Date().toLocaleTimeString(this.loc),
        `<div class="big">${title}</div><div>${what}</div>${img}`, "alert");
    }

    const alarmTxt = !alarmS ? "—" : ({ disarmed: this.t("désarmée"), armed_away: this.t("armée (absent)"),
      armed_home: this.t("armée (présent)"), armed_night: this.t("armée (nuit)"), arming: this.t("armement…") }[alarmS.state] || this.esc(alarmS.state));
    const chip = (id, label, kind) => {
      if (!this.ok(id)) return `<span class="chip ${kind} mute click" data-e="${id}">${label} · ${this.t("muet")}</span>`;
      const on = this.st(id).state === "on";
      return `<span class="chip ${kind} click ${on ? "on" : "ok"}" data-e="${id}">${label}${on && kind === "door" ? ` · ${this.t("ouverte")}` : ""}</span>`;
    };
    const short = (id) => this._name(id).replace(/^(Fuite|Ouverture|Leak|Opening)\s*/i, "")
      .replace(/\s*(Humidité|Contact|Porte|Door|Humidity)$/i, "").replace(/\bEntree\b/, "entrée");
    return this.frame(this.t("Sécurité"), mute.length ? this.t("{n} capteur(s) muet(s)", { n: mute.length }) : this.t("veille"),
      `<div class="calm">
         <div><div class="lbl">${this.t("État")}</div><div class="state">${this.t("NORMAL")}</div></div>
         <div class="click" data-e="${c.alarm}"><div class="lbl">${this.t("Alarme")}</div><div class="val">${alarmTxt}</div></div>
         ${c.hide_sim ? "" : `<button class="sim">▶ ${this.t("simuler une sonnette")}</button>`}
       </div>
       <div class="chips"><span class="lbl" style="align-self:center">${this.t("Fuites")}</span>${c.leaks.map((id) => chip(id, short(id), "leak")).join("")}</div>
       <div class="chips" style="margin-top:6px"><span class="lbl" style="align-self:center">${this.t("Ouvrants")}</span>${c.doors.map((id) => chip(id, short(id), "door")).join("")}</div>`);
  }
  afterRender() {
    const b = this.shadowRoot.querySelector(".sim");
    if (b) b.addEventListener("click", (ev) => {
      ev.stopPropagation();
      this._simUntil = Date.now() + 8000;
      this._schedule();
      setTimeout(() => this._schedule(), 8100);
    });
  }
}

/* ------------------------------------------------------------------ HANGAR */
/*
 * type: custom:sf-hangar-card
 * cars:
 *   - name: Car A
 *     soc: sensor.x            # %
 *     range: sensor.x          # km
 *     charging: binary_sensor.x | sensor.x   # optionnel
 *     color: "#00e5ff"
 * charger:
 *   connected: binary_sensor.x
 *   charging: binary_sensor.x
 *   power: sensor.x            # W
 *   current: number.x          # A
 *   decision: sensor.x         # décision du pilote de charge (facultatif)
 */
class SfHangarCard extends SfBase {
  defaults() { return { cars: [], charger: {} }; }
  css() {
    return `
      .bay { display:grid; grid-template-columns: 1fr auto 1fr; align-items:center; gap:8px; }
      .car { text-align:center; }
      .car .name { font-family:Orbitron,sans-serif; letter-spacing:.14em; font-size:12px; margin-top:4px; }
      .car .km { font-size:11px; color:${SF_C.dim}; margin-top:2px; }
      .ring-bg { fill:none; stroke:rgba(255,255,255,.07); stroke-width:7; }
      .ring { fill:none; stroke-width:7; stroke-linecap:round; transform:rotate(-90deg); transform-origin:50% 50%;
        transition: stroke-dashoffset 1s ease; }
      .soc { font-family:Orbitron,sans-serif; font-size:20px; fill:#fff; }
      .tick { stroke:rgba(0,229,255,.25); stroke-width:1; }
      .borne { text-align:center; min-width:92px; }
      .borne .plug { font-size:26px; }
      .flow { width:90px; height:4px; margin:8px auto; border-radius:2px; background:rgba(255,255,255,.08); overflow:hidden; }
      .flow.on::before { content:""; display:block; width:40%; height:100%;
        background: linear-gradient(90deg, transparent, ${SF_C.green}, transparent); animation: run 1.1s linear infinite; }
      @keyframes run { from { transform:translateX(-100%); } to { transform:translateX(250%); } }
      .note { margin-top:14px; padding-top:10px; border-top:1px dashed rgba(0,229,255,.18);
        display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap; font-size:11px; }
      .badge { display:inline-block; padding:2px 8px; border-radius:10px; font-size:10px; margin-top:6px;
        border:1px solid rgba(43,255,136,.45); color:${SF_C.green}; }
      .warnbox { margin-top:10px; padding:9px 12px; border-radius:8px; font-size:11.5px; line-height:1.4;
        color:${SF_C.amber}; border:1px solid rgba(255,179,0,.55); background:rgba(255,179,0,.09); animation: blink 2s infinite; }
      .fl3 { display:grid; grid-template-columns: repeat(3, 1fr); gap:8px; margin-top:12px; }
      .fl3 > div { padding:7px 9px; border-radius:8px; background:rgba(0,229,255,.04); border:1px solid rgba(0,229,255,.12); }
      .tgt { stroke:#fff; stroke-width:2; }`;
  }
  _ring(car) {
    const soc = this.num(car.soc);
    const r = 42, L = 2 * Math.PI * r;
    const pct = soc === null ? 0 : Math.max(0, Math.min(100, soc));
    const col = soc === null ? SF_C.grey : pct < 20 ? SF_C.red : pct < 40 ? SF_C.amber : (car.color || SF_C.cyan);
    const ticks = Array.from({ length: 24 }, (_, i) => {
      const a = (i / 24) * 2 * Math.PI;
      return `<line class="tick" x1="${55 + 50 * Math.cos(a)}" y1="${55 + 50 * Math.sin(a)}" x2="${55 + 53 * Math.cos(a)}" y2="${55 + 53 * Math.sin(a)}"/>`;
    }).join("");
    return `<svg viewBox="0 0 110 110" width="118" height="118" class="click" data-e="${car.soc}">
      ${ticks}<circle class="ring-bg" cx="55" cy="55" r="${r}"/>
      <circle class="ring" cx="55" cy="55" r="${r}" stroke="${col}" stroke-dasharray="${L}"
        stroke-dashoffset="${L * (1 - pct / 100)}" style="filter:drop-shadow(0 0 5px ${col})"/>
      ${this._target(car)}
      <text class="soc" x="55" y="62" text-anchor="middle">${soc === null ? "—" : Math.round(soc) + "%"}</text></svg>`;
  }
  // Repère blanc à la charge cible (ex. 80 %), si la voiture la publie.
  _target(car) {
    const t = this.num(car.target); if (t === null) return "";
    const a = (t / 100) * 2 * Math.PI - Math.PI / 2;
    return `<line class="tgt" x1="${55 + 36 * Math.cos(a)}" y1="${55 + 36 * Math.sin(a)}" x2="${55 + 48 * Math.cos(a)}" y2="${55 + 48 * Math.sin(a)}"><title>cible ${Math.round(t)} %</title></line>`;
  }
  _car(car) {
    const chargingS = this.st(car.charging);
    const charging = chargingS && ["on", "charging", "true"].includes(String(chargingS.state).toLowerCase());
    return `<div class="car">${this._ring(car)}
      <div class="name">${car.name}</div>
      <div class="km click" data-e="${car.range}">${this.t("{n} km d'autonomie", { n: this.fmt(car.range) })}</div>
      ${charging ? `<span class="badge">${this.t("EN CHARGE")}</span>` : ""}</div>`;
  }
  render() {
    const c = this._config, ch = c.charger || {};
    const connected = this.st(ch.connected) && this.st(ch.connected).state === "on";
    const charging = this.st(ch.charging) && this.st(ch.charging).state === "on";
    const p = this.num(ch.power);
    const cars = c.cars.slice(0, 2);
    const borne = `<div class="borne">
        <div class="lbl">${this.t("Borne")}</div>
        <div class="plug click" data-e="${ch.connected}" style="color:${connected ? SF_C.green : SF_C.grey};filter:drop-shadow(0 0 6px currentColor)"><ha-icon icon="mdi:ev-station" style="--mdc-icon-size:30px"></ha-icon></div>
        <div class="flow ${charging ? "on" : ""}"></div>
        <div class="val click" data-e="${ch.power}">${p === null ? "—" : Math.round(p) + " W"}</div>
        <div class="lbl click" data-e="${ch.current}">${this.fmt(ch.current)} A</div></div>`;
    const who = connected
      ? `<span>${this.t("Câble branché")} · <span style="color:${SF_C.amber}">${this.t("voiture non identifiée par HA")}</span></span>`
      : `<span class="muted">${this.t("Aucun véhicule branché")}</span>`;
    const dec = ch.decision ? `<span class="click" data-e="${ch.decision}">${this.t("Pilote")} : <b style="color:${SF_C.cyan}">${this.fmt(ch.decision)}</b></span>` : "";
    return this.frame(this.t("Véhicules"), charging ? this.t("charge en cours") : connected ? this.t("en attente") : this.t("au repos"),
      `<div class="bay">${cars[0] ? this._car(cars[0]) : "<div></div>"}${borne}${cars[1] ? this._car(cars[1]) : "<div></div>"}</div>
       <div class="note">${who}${dec}</div>${this._modes(connected)}${this._flows()}`);
  }
  // Sélecteur du mode de charge (input_select) + garde-fou : voiture branchée le soir
  // en « Surplus » seul = pas de charge de nuit.
  _modes(connected) {
    const c = this._config, m = this.st(c.mode);
    if (!m) return "";
    const h = new Date().getHours();
    const warn = c.warn_mode && connected && m.state === c.warn_mode && (h >= 17 || h < 6);
    const opts = (m.attributes.options || []).map((o) =>
      `<span class="btn ${m.state === o ? "on" : ""}" ${this.call("input_select.select_option", { entity_id: c.mode, option: o })}>${this.esc(o)}</span>`).join("");
    return `<div style="margin-top:12px"><div class="lbl" style="margin-bottom:6px">${this.t("Mode de charge")}</div><div class="seg">${opts}</div>
      ${warn ? `<div class="warnbox">${this.esc(c.warn_text || "")}</div>` : ""}</div>`;
  }
  _flows() {
    const f = this._config.flows; if (!f) return "";
    const cell = (lbl, id, col) => { const w = this.watts(id); return `<div class="click" data-e="${id}"><div class="lbl">${lbl}</div><div class="val" style="color:${col}">${this.kw(w)}</div></div>`; };
    const cells = [f.solar && cell(this.t("Solaire"), f.solar, SF_C.amber), f.home && cell(this.t("Maison hors VE"), f.home, SF_C.cyan),
      f.surplus && cell(this.t("Surplus"), f.surplus, (this.watts(f.surplus) ?? 0) >= 0 ? SF_C.green : "#ff7a45")].filter(Boolean);
    return cells.length ? `<div class="fl3" style="grid-template-columns:repeat(${cells.length},1fr)">${cells.join("")}</div>` : "";
  }
}

/* ------------------------------------------------------------------- RADAR */
/*
 * Trois anneaux, trois sources, AUCUNE fusion (principe de conception) :
 *   anneau extérieur  : person.*            -> à la maison ou non (réseau/GPS), sans pièce
 *   anneau du milieu  : Frigate (visage)    -> dernière caméra où la personne a été reconnue
 *   anneau intérieur  : capteurs de pièce   -> occupation, SANS identité
 * Une même personne apparaît sur deux anneaux distincts : la carte ne déduit jamais
 * « Alice est au salon » en croisant deux sources.
 *
 * type: custom:sf-radar-card
 * people: [{ name, person, face, color }]   # face = sensor.<x>_last_camera
 * rooms:  [{ label, entity }]               # binary_sensor occupation
 */
class SfRadarCard extends SfBase {
  defaults() { return { people: [], rooms: [] }; }
  css() {
    return `
      .wrap { display:grid; grid-template-columns: minmax(200px, 300px) 1fr; gap:14px; align-items:center; }
      @media (max-width: 520px) { .wrap { grid-template-columns: 1fr; } }
      .radar { position:relative; width:100%; aspect-ratio:1; }
      .radar svg { position:absolute; inset:0; width:100%; height:100%; }
      .sweep { position:absolute; inset:4%; border-radius:50%;
        background: conic-gradient(from 0deg, rgba(0,229,255,.32), rgba(0,229,255,0) 22%, transparent 100%);
        animation: spin 4.5s linear infinite; mask: radial-gradient(circle, #000 69%, transparent 70%); }
      @keyframes spin { to { transform: rotate(360deg); } }
      .ringl { fill:none; stroke:rgba(0,229,255,.22); stroke-dasharray:3 4; }
      .cross { stroke:rgba(0,229,255,.12); }
      .rl { font-size:2.6px; fill:${SF_C.dim}; letter-spacing:.18em; }
      .blip { transition: opacity .5s; }
      .legend .row { display:flex; justify-content:space-between; gap:10px; padding:5px 0;
        border-bottom:1px solid rgba(0,229,255,.08); font-size:12px; }
      .legend h4 { margin:10px 0 4px; font-family:Orbitron,sans-serif; font-weight:500; font-size:10px;
        letter-spacing:.18em; color:${SF_C.cyan}; }
      .legend h4:first-child { margin-top:0; }
      .rule { margin-top:10px; font-size:10px; color:${SF_C.dim}; }`;
  }
  render() {
    const c = this._config;
    const R = { outer: 46, mid: 32, inner: 18 };
    const pos = (radius, i, n, offset) => {
      const a = (offset + (i / Math.max(n, 1)) * 360) * Math.PI / 180;
      return [50 + radius * Math.cos(a), 50 + radius * Math.sin(a)];
    };
    const blip = (x, y, col, on, label) => `<g class="blip" opacity="${on ? 1 : 0.28}">
        <circle cx="${x}" cy="${y}" r="${on ? 2.6 : 1.8}" fill="${col}" style="filter:drop-shadow(0 0 2px ${col})"/>
        ${on ? `<circle cx="${x}" cy="${y}" r="2.6" fill="none" stroke="${col}" stroke-width=".6"><animate attributeName="r" from="2.6" to="7" dur="1.8s" repeatCount="indefinite"/><animate attributeName="opacity" from=".8" to="0" dur="1.8s" repeatCount="indefinite"/></circle>` : ""}
        <text x="${x}" y="${y - 3.8}" text-anchor="middle" font-size="3.2" fill="${on ? "#fff" : SF_C.grey}">${label}</text></g>`;
    const np = c.people.length, nr = c.rooms.length;
    let svg = `<circle class="ringl" cx="50" cy="50" r="${R.outer}"/><circle class="ringl" cx="50" cy="50" r="${R.mid}"/>
      <circle class="ringl" cx="50" cy="50" r="${R.inner}"/>
      <line class="cross" x1="50" y1="2" x2="50" y2="98"/><line class="cross" x1="2" y1="50" x2="98" y2="50"/>
      <text class="rl" x="50" y="${50 - R.outer - 1.2}" text-anchor="middle">${this.t("RÉSEAU")}</text>
      <text class="rl" x="50" y="${50 - R.mid - 1.2}" text-anchor="middle">${this.t("VISAGE")}</text>
      <text class="rl" x="50" y="${50 - R.inner - 1.2}" text-anchor="middle">${this.t("PIÈCES")}</text>
      <circle cx="50" cy="50" r="2" fill="${SF_C.cyan}"/>`;
    const peopleRows = [], faceRows = [], roomRows = [];
    c.people.forEach((p, i) => {
      const col = p.color || SF_C.cyan;
      if (p.person) {  // pas d'entité person (ex. personne sans téléphone) : absent de cet anneau
        const home = this.st(p.person) && this.st(p.person).state === "home";
        const [x1, y1] = pos(R.outer, i, np, -60);
        svg += blip(x1, y1, col, home, p.name);
        peopleRows.push(`<div class="row click" data-e="${p.person}"><span style="color:${col}">${p.name}</span><span>${!this.ok(p.person) ? "—" : home ? this.t("à la maison") : this.t("absent·e")}</span></div>`);
      }
      if (p.face) {
        const cam = this.ok(p.face) ? this.st(p.face).state : null;
        const seen = cam && cam.toLowerCase() !== "unknown";
        const [x2, y2] = pos(R.mid, i, np, 20);
        svg += blip(x2, y2, col, seen, p.name);
        faceRows.push(`<div class="row click" data-e="${p.face}"><span style="color:${col}">${p.name}</span><span>${seen ? `${this.esc(cam)} · ${this.ago(p.face)}` : this.t("jamais vu·e")}</span></div>`);
      }
    });
    c.rooms.forEach((r, i) => {
      const on = this.st(r.entity) && this.st(r.entity).state === "on";
      const [x, y] = pos(R.inner, i, nr, 90);
      svg += blip(x, y, SF_C.amber, on, r.label);
      roomRows.push(`<div class="row click" data-e="${r.entity}"><span>${r.label}</span><span>${!this.ok(r.entity) ? "—" : on ? this.t("occupée") : this.t("vide")}</span></div>`);
    });
    return this.frame(this.t("Radar de présence"), this.t("3 sources indépendantes"),
      `<div class="wrap"><div class="radar"><div class="sweep"></div><svg viewBox="0 0 100 100">${svg}</svg></div>
        <div class="legend"><h4>${this.t("Réseau / GPS")}</h4>${peopleRows.join("")}
          <h4>${this.t("Visage Frigate · dernière vue")}</h4>${faceRows.join("") || '<div class="row muted">—</div>'}
          <h4>${this.t("Capteurs de pièce · sans identité")}</h4>${roomRows.join("") || '<div class="row muted">—</div>'}
          <div class="rule">${this.t("Les anneaux ne sont jamais croisés : aucune position n'est déduite.")}</div></div></div>`);
  }
  getCardSize() { return 6; }
}

/* ---------------------------------------------------------------- MACHINES */
/*
 * type: custom:sf-machines-card
 * tiles:
 *   - label: CPU host
 *     entity: sensor.x
 *     kind: percent | value | binary | duration | timestamp | text
 *     warn: 70          # seuils (percent/value) ; invert: true si « bas = mauvais »
 *     crit: 90
 *     invert: false
 *     ok_state: "on"    # binary : état considéré OK
 *     unit: "°C"        # forcer l'unité
 */
class SfMachinesCard extends SfBase {
  defaults() { return { tiles: [] }; }
  css() {
    return `
      .grid { display:grid; grid-template-columns: repeat(auto-fill, minmax(132px, 1fr)); gap:10px; }
      .tile { position:relative; padding:10px 11px 12px; border-radius:10px;
        background: linear-gradient(160deg, rgba(0,229,255,.07), rgba(0,229,255,.015));
        border:1px solid rgba(0,229,255,.16); }
      .tile .v { font-family:Orbitron,sans-serif; font-size:19px; margin-top:6px; }
      .tile .u { font-size:10px; color:${SF_C.dim}; margin-left:3px; }
      .bar { height:3px; margin-top:8px; border-radius:2px; background:rgba(255,255,255,.07); overflow:hidden; }
      .bar i { display:block; height:100%; border-radius:2px; transition: width 1s; }
      .led { position:absolute; top:10px; right:10px; width:7px; height:7px; border-radius:50%; }
      .pulse { height:26px; margin-top:12px; opacity:.75; }
      .pulse path { fill:none; stroke:${SF_C.cyan}; stroke-width:1.4; stroke-dasharray:40 220;
        animation: beat 2.4s linear infinite; filter:drop-shadow(0 0 3px ${SF_C.cyan}); }
      @keyframes beat { from { stroke-dashoffset:260; } to { stroke-dashoffset:0; } }`;
  }
  _dur(sec) {
    const h = Math.floor(sec / 3600), m = Math.round((sec % 3600) / 60);
    return h ? `${h}h${String(m).padStart(2, "0")}` : `${m} min`;
  }
  _tile(t) {
    const id = t.entity, kind = t.kind || "value";
    if (kind === "toggle") {
      // `timer` + `stop` : tant que le minuteur tourne, la tuile affiche le temps restant et un appui l'arrête (2 appuis).
      const tm = this.timerInfo(t.timer), dead = !this.ok(id);
      const on = tm.actif || this.isOn(id), col = dead ? SF_C.grey : on ? (t.color || SF_C.cyan) : SF_C.grey;
      const act = tm.actif && t.stop ? this.call("homeassistant.turn_off", { entity_id: t.stop }, this.t("Arrêter ?")) : this.toggleCall(id);
      const txt = dead ? "—" : tm.actif ? (tm.reste === null ? "ON" : `${tm.reste} min`) : on ? "ON" : "OFF";
      return `<div class="tile" ${act} style="cursor:pointer">
        <span class="led" style="background:${col};box-shadow:0 0 6px ${col}"></span>
        <div class="lbl">${this.esc(t.label)}</div><div class="v" style="color:${dead ? SF_C.grey : "#fff"}">${txt}</div></div>`;
    }
    let v = "—", u = "", col = SF_C.grey, pct = null;
    if (this.ok(id)) {
      const s = this.st(id), n = this.num(id);
      col = SF_C.green;
      if (kind === "binary") {
        const good = s.state === (t.ok_state || "on");
        v = good ? "OK" : (t.bad_text || "KO"); col = good ? SF_C.green : SF_C.red;
      } else if (kind === "duration" && n !== null) {
        v = this._dur(n); pct = t.max ? Math.min(100, (n / t.max) * 100) : null;
        if (t.warn !== undefined && n < t.warn) col = SF_C.amber;
      } else if (kind === "timestamp") {
        const d = new Date(s.state);
        v = isNaN(d) ? s.state : d.toLocaleString("fr-FR", { weekday: "short", hour: "2-digit", minute: "2-digit" });
        col = SF_C.cyan;
      } else if (kind === "text" || n === null) {
        v = t.map && t.map[s.state] ? t.map[s.state] : s.state;
        col = t.ok_values && !t.ok_values.includes(s.state) ? SF_C.amber : SF_C.cyan;
      } else {
        v = n.toFixed(t.digits ?? (Math.abs(n) < 10 ? 1 : 0)); u = t.unit ?? this.unit(id);
        if (kind === "percent") pct = Math.max(0, Math.min(100, n));
        else if (t.max) pct = Math.max(0, Math.min(100, (n / t.max) * 100));
        const bad = (lim) => (t.invert ? n <= lim : n >= lim);
        if (t.crit !== undefined && bad(t.crit)) col = SF_C.red;
        else if (t.warn !== undefined && bad(t.warn)) col = SF_C.amber;
        else if (t.low !== undefined && n < t.low) col = SF_C.amber;   // seuil bas (ex. eau d'un bac trop froide)
      }
    }
    return `<div class="tile click" data-e="${id}">
      <span class="led" style="background:${col};box-shadow:0 0 6px ${col}"></span>
      <div class="lbl">${this.esc(t.label)}</div><div class="v" style="color:${col === SF_C.grey ? SF_C.grey : "#fff"}">${this.esc(v)}<span class="u">${this.esc(u)}</span></div>
      ${pct !== null ? `<div class="bar"><i style="width:${pct}%;background:${col};box-shadow:0 0 6px ${col}"></i></div>` : ""}</div>`;
  }
  render() {
    const tiles = this._config.tiles;
    const bad = tiles.filter((t) => !this.ok(t.entity)).length;
    return this.frame(this.esc(this._config.title || this.t("Équipements")), bad ? this.t("{n} capteur(s) sans réponse", { n: bad }) : this.t("tout fonctionne"),
      `<div class="grid">${tiles.map((t) => this._tile(t)).join("")}</div>
       <svg class="pulse" viewBox="0 0 200 26" preserveAspectRatio="none" width="100%"><path d="M0 13 H70 L78 4 L86 22 L94 13 H200"/></svg>`);
  }
  getCardSize() { return 5; }
}

/* ================================================================== PONT */
/*
 * Bandeau de commandement plein cadre : heure, météo, tarif, mode maison, équipage,
 * et la liste des anomalies du moment (ou « tous systèmes nominaux »).
 *
 * type: custom:sf-bridge-card
 * weather: weather.x            outdoor: sensor.x (température extérieure)
 * price: sensor.x (€/kWh)        hc_price: input_number.x (prix HC, pour savoir HP/HC)
 * hc_windows: [{ start: "00:56", end: "06:56" }, { start: "14:26", end: "16:26" }]   # compte à rebours HP/HC (le prix décide de HP ou HC)
 * mode: input_select.x           solar_left: sensor.x (kWh solaires restants aujourd'hui)
 * people: [{ name, entity, color }]    home_states: [home]   # états comptés « à la maison » (ex. [home, "Ma zone"])
 * power_in: sensor.x (tension secteur, < 200 V = coupure)  internet: binary_sensor.x
 * leaks: [..]  doors: [..]
 */
const SF_WEATHER = {
  "clear-night": ["Nuit claire", "mdi:weather-night"], sunny: ["Ensoleillé", "mdi:weather-sunny"],
  partlycloudy: ["Éclaircies", "mdi:weather-partly-cloudy"], cloudy: ["Nuageux", "mdi:weather-cloudy"],
  rainy: ["Pluie", "mdi:weather-rainy"], pouring: ["Averses", "mdi:weather-pouring"],
  fog: ["Brouillard", "mdi:weather-fog"], snowy: ["Neige", "mdi:weather-snowy"],
  "snowy-rainy": ["Neige fondue", "mdi:weather-snowy-rainy"], windy: ["Venteux", "mdi:weather-windy"],
  "windy-variant": ["Venteux", "mdi:weather-windy-variant"], lightning: ["Orage", "mdi:weather-lightning"],
  "lightning-rainy": ["Orage", "mdi:weather-lightning-rainy"], hail: ["Grêle", "mdi:weather-hail"],
  exceptional: ["Alerte météo", "mdi:alert"],
};
class SfBridgeCard extends SfBase {
  defaults() { return { people: [], leaks: [], doors: [], home_states: ["home"] }; }
  connectedCallback() {
    this._tick = setInterval(() => {
      const el = this.shadowRoot && this.shadowRoot.querySelector(".clock .s");
      if (el) el.textContent = String(new Date().getSeconds()).padStart(2, "0");
      if (new Date().getSeconds() === 0) this._schedule();
    }, 1000);
  }
  disconnectedCallback() { clearInterval(this._tick); }
  css() {
    return `
      .hud.bridge { padding:22px 26px 20px; min-height:170px; }
      .floor { position:absolute; left:-50%; right:-50%; bottom:-40%; height:120%; pointer-events:none;
        transform: perspective(260px) rotateX(72deg); transform-origin:50% 100%; opacity:.55;
        background-image: linear-gradient(rgba(0,229,255,.35) 1px, transparent 1px),
                          linear-gradient(90deg, rgba(0,229,255,.35) 1px, transparent 1px);
        background-size: 46px 46px; animation: travel 3s linear infinite;
        mask-image: linear-gradient(to top, #000 0%, transparent 75%); -webkit-mask-image: linear-gradient(to top, #000 0%, transparent 75%); }
      @keyframes travel { to { background-position: 0 46px, 0 0; } }
      .horizon { position:absolute; left:0; right:0; top:58%; height:2px; pointer-events:none;
        background: linear-gradient(90deg, transparent, rgba(0,229,255,.8), transparent); filter: blur(1px); }
      .top { position:relative; display:grid; grid-template-columns: auto 1fr auto; gap:28px; align-items:center; }
      @media (max-width: 900px) { .top { grid-template-columns: 1fr; gap:14px; } }
      .clock { font-family:Orbitron,sans-serif; font-weight:700; font-size:54px; line-height:1; color:#fff;
        text-shadow: 0 0 18px rgba(0,229,255,.75), 0 0 2px #fff; letter-spacing:.04em; }
      .clock .s { font-size:22px; color:${SF_C.cyan}; margin-left:4px; }
      .date { margin-top:6px; letter-spacing:.24em; text-transform:uppercase; font-size:11px; color:${SF_C.dim}; }
      .status { text-align:center; }
      .status .big { font-family:Orbitron,sans-serif; font-weight:700; letter-spacing:.18em; font-size:17px; }
      .status .chips { display:flex; flex-wrap:wrap; gap:6px; justify-content:center; margin-top:10px; }
      .an { padding:5px 10px; border-radius:20px; font-size:11px; border:1px solid; }
      .an.red { color:${SF_C.red}; border-color:rgba(255,51,85,.6); background:rgba(255,51,85,.1); animation: blink 1.2s infinite; }
      .an.amber { color:${SF_C.amber}; border-color:rgba(255,179,0,.5); background:rgba(255,179,0,.08); }
      .meta { display:grid; grid-template-columns: repeat(2, minmax(120px, auto)); gap:10px 22px; }
      .meta .v { font-family:Orbitron,sans-serif; font-size:15px; color:#fff; margin-top:2px; display:flex; align-items:center; gap:6px; }
      .crew { position:relative; display:flex; gap:10px; flex-wrap:wrap; margin-top:18px; padding-top:12px;
        border-top:1px solid rgba(0,229,255,.14); align-items:center; }
      .member { display:flex; align-items:center; gap:7px; padding:4px 12px 4px 4px; border-radius:20px;
        background:rgba(255,255,255,.03); border:1px solid rgba(255,255,255,.08); font-size:12px; }
      .member .av { width:24px; height:24px; border-radius:50%; display:grid; place-items:center;
        font-family:Orbitron,sans-serif; font-size:11px; color:#03080f; }
      .member.away { opacity:.45; }
      .crew .right { margin-left:auto; font-size:11px; color:${SF_C.dim}; }`;
  }
  // HP/HC : le prix en cours fait foi (il vient du capteur de tarif, qui connaît les vraies plages du contrat).
  // Les plages `hc_windows` ne servent qu'au compte à rebours — et de secours si le prix est indisponible.
  _isHC(now) {
    const c = this._config, toMin = (x) => { const [h, m] = String(x).split(":").map(Number); return h * 60 + m; };
    const wins = (c.hc_windows && c.hc_windows.length ? c.hc_windows : [{ start: c.hc_start || "22:00", end: c.hc_end || "06:00" }])
      .map((w) => [toMin(w.start), toMin(w.end)]);
    const t = now.getHours() * 60 + now.getMinutes();
    let hc = wins.some(([a, b]) => (a > b ? (t >= a || t < b) : (t >= a && t < b)));
    const price = this.num(c.price), hcp = this.num(c.hc_price);
    if (price !== null && hcp !== null) hc = Math.abs(price - hcp) < 0.0005;
    const edges = wins.map((w) => w[hc ? 1 : 0]);
    const left = Math.min(...edges.map((e) => { const d = (e - t + 1440) % 1440; return d === 0 ? 1440 : d; }));
    return { hc, left };
  }
  render() {
    const c = this._config, now = new Date();
    const hh = String(now.getHours()).padStart(2, "0"), mm = String(now.getMinutes()).padStart(2, "0");
    const date = now.toLocaleDateString(this.loc, { weekday: "long", day: "numeric", month: "long", year: "numeric" });

    const an = [];
    const v = this.num(c.power_in);
    if (c.power_in && (v === null || v < 200)) an.push(["red", v === null ? this.t("Onduleur muet") : this.t("Coupure secteur · {v} V", { v: Math.round(v) }), c.power_in]);
    c.leaks.forEach((id) => { if (this.st(id) && this.st(id).state === "on") an.push(["red", this.t("Fuite · {n}", { n: this._short(id) }), id]); });
    if (c.internet && this.st(c.internet) && this.st(c.internet).state === "off") an.push(["red", this.t("Internet coupé"), c.internet]);
    c.doors.forEach((id) => { if (this.st(id) && this.st(id).state === "on") an.push(["amber", this.t("{n} ouverte", { n: this._short(id) }), id]); });
    c.leaks.forEach((id) => { if (!this.ok(id)) an.push(["amber", this.t("Fuite {n} · muet", { n: this._short(id) }), id]); });
    const reds = an.filter((a) => a[0] === "red").length;
    const status = an.length
      ? `<div class="big" style="color:${reds ? SF_C.red : SF_C.amber}">${this.t("{s} · {n} point(s)", { s: this.t(reds ? "ALERTE" : "VIGILANCE"), n: an.length })}</div>
         <div class="chips">${an.map(([k, t, id]) => `<span class="an ${k} click" data-e="${id}">${this.esc(t)}</span>`).join("")}</div>`
      : `<div class="big" style="color:${SF_C.green};text-shadow:0 0 12px rgba(43,255,136,.6)">${this.t("TOUT EST NORMAL")}</div>
         <div class="lbl" style="margin-top:8px">${this.t("portes fermées · aucune fuite · secteur OK")}</div>`;

    const w = this.st(c.weather);
    const [wTxt0, wIco] = (w && SF_WEATHER[w.state]) || [w ? this.esc(w.state) : "—", "mdi:weather-cloudy-alert"];
    const wTxt = w && SF_WEATHER[w.state] ? this.t(wTxt0) : wTxt0;
    const out = this.num(c.outdoor);
    const { hc, left } = this._isHC(now);
    const price = this.num(c.price);
    const mode = this.st(c.mode);
    const modeTxt = mode ? this.esc(mode.state.replace(/^[^\p{L}]+/u, "")) : "—";
    const sol = this.num(c.solar_left);

    const crew = c.people.map((p) => {
      // « à la maison » = état `home`, ou l'un des états de `home_states` (zone maison personnalisée, plus petite que « home »).
      const hs = (c.home_states || ["home"]).map((x) => String(x).trim().toLowerCase());
      const home = this.st(p.entity) && hs.includes(String(this.st(p.entity).state).trim().toLowerCase());
      return `<span class="member click ${home ? "" : "away"}" data-e="${p.entity}"><span class="av" style="background:${p.color || SF_C.cyan};box-shadow:0 0 8px ${p.color || SF_C.cyan}">${this.esc(p.name[0])}</span>${this.esc(p.name)} · ${home ? this.t("à la maison") : this.t("absent·e")}</span>`;
    }).join("");

    return `<div class="hud bridge"><div class="floor"></div><div class="horizon"></div>
      <i class="c tl"></i><i class="c tr"></i><i class="c bl"></i><i class="c br"></i>
      <div class="top">
        <div><div class="clock">${hh}:${mm}<span class="s">${String(now.getSeconds()).padStart(2, "0")}</span></div>
          <div class="date">${this.esc(date)}</div></div>
        <div class="status">${status}</div>
        <div class="meta">
          <div class="click" data-e="${c.weather}"><div class="lbl">${this.t("Extérieur")}</div><div class="v">${this.icon(wIco, 18, SF_C.cyan)}${out === null ? "—" : out.toFixed(1) + "°"}</div><div class="lbl" style="margin-top:2px">${wTxt}</div></div>
          <div class="click" data-e="${c.price}"><div class="lbl">${this.t("Tarif")}</div><div class="v" style="color:${hc ? SF_C.green : SF_C.amber}">${this.t(hc ? "HC" : "HP")} <span style="font-size:11px;color:${SF_C.text}">${price === null ? "" : price.toFixed(3) + " €"}</span></div><div class="lbl" style="margin-top:2px">${this.t("{x} dans {h}h{m}", { x: this.t(hc ? "HP" : "HC"), h: Math.floor(left / 60), m: String(left % 60).padStart(2, "0") })}</div></div>
          ${c.mode ? `<div class="click" data-e="${c.mode}"><div class="lbl">${this.t("Mode maison")}</div><div class="v">${modeTxt}</div></div>` : ""}
          ${c.solar_left ? `<div class="click" data-e="${c.solar_left}"><div class="lbl">${this.t("Solaire restant")}</div><div class="v">${this.icon("mdi:solar-power-variant", 16, SF_C.amber)}${sol === null ? "—" : sol.toFixed(1) + " kWh"}</div></div>` : ""}
        </div>
      </div>
      ${c.people.length ? `<div class="crew"><span class="lbl">${this.t("Présence")}</span>${crew}<span class="right">${this.esc(c.footer || "")}</span></div>` : ""}</div>`;
  }
  _short(id) {
    const s = this.st(id), n = (s && s.attributes.friendly_name) || id;
    return this.esc(n.replace(/^(Fuite|Ouverture)\s*/i, "").replace(/\s*(Humidité|Contact|Porte|Water leak)$/i, ""));
  }
  getCardSize() { return 4; }
}

/* =============================================================== RÉACTEUR */
/*
 * Flux d'énergie autour d'un cœur 3D. Les puissances sont converties en W quelle
 * que soit l'unité (certains compteurs publient en kW).
 *
 * type: custom:sf-reactor-card
 * solar: sensor.x (facultatif)    grid: sensor.x (positif = soutirage du réseau)
 * battery_power: sensor.x (W, positif = décharge)   battery_soc: sensor.x (%)   battery_invert: false   # batterie facultative
 * devices: [{ name, entity, icon, color }]
 * hide_idle: true   idle_w: 20   # masque les appareils sous 20 W (la disposition ne porte que sur les visibles)
 * max_devices: 8                 # au-delà, seuls les plus gourmands sont affichés (« +N autres »)
 * fossil: sensor.x (% fossile du réseau)   price: sensor.x
 */
class SfReactorCard extends SfBase {
  defaults() { return { devices: [], hide_idle: true, idle_w: 20, max_devices: 8 }; }
  // La disposition dépend de la largeur disponible : on re-rend quand elle change (rotation, redimensionnement).
  connectedCallback() {
    if (typeof ResizeObserver === "undefined") return;
    this._ro = new ResizeObserver(() => this._schedule());
    this._ro.observe(this);
  }
  disconnectedCallback() { if (this._ro) { this._ro.disconnect(); this._ro = null; } }
  css() {
    return `
      .stage { position:relative; width:100%; aspect-ratio: 16 / 9; min-height:260px; }
      .stage svg { position:absolute; inset:0; width:100%; height:100%; }
      .ln { fill:none; stroke-width:2; stroke-linecap:round; }
      .ln.bg { stroke:rgba(255,255,255,.06); stroke-width:6; }
      .ln.fx { stroke-dasharray: 2 14; animation: flow var(--d, 2s) linear infinite; }
      .ln.rev { animation-direction: reverse; }
      @keyframes flow { to { stroke-dashoffset: -32; } }
      .node { position:absolute; transform:translate(-50%,-50%); text-align:center; width:88px; }
      .node .ic { width:46px; height:46px; margin:0 auto 4px; border-radius:50%; display:grid; place-items:center;
        background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.12), rgba(0,0,0,.4));
        border:1px solid currentColor; box-shadow: 0 0 12px -2px currentColor, inset 0 0 10px -4px currentColor; }
      .node .n { font-size:9px; letter-spacing:.14em; text-transform:uppercase; color:${SF_C.dim}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
      .node .w { font-family:Orbitron,sans-serif; font-size:13px; color:#fff; }
      .node.idle { opacity:.4; }
      .core { position:absolute; left:50%; top:50%; width:min(30%, 190px); aspect-ratio:1; transform:translate(-50%,-50%);
        perspective: 600px; }
      .core .r { position:absolute; inset:0; border-radius:50%; border:2px solid var(--cc);
        box-shadow: 0 0 14px var(--cc), inset 0 0 14px var(--cc); opacity:.75; transform-style:preserve-3d; }
      .core .r1 { animation: o1 7s linear infinite; }
      .core .r2 { inset:8%; animation: o2 9s linear infinite; border-style:dashed; }
      .core .r3 { inset:16%; animation: o3 5s linear infinite; opacity:.5; }
      @keyframes o1 { from { transform: rotateX(70deg) rotateZ(0); } to { transform: rotateX(70deg) rotateZ(360deg); } }
      @keyframes o2 { from { transform: rotateY(65deg) rotateZ(0); } to { transform: rotateY(65deg) rotateZ(-360deg); } }
      @keyframes o3 { from { transform: rotateX(-40deg) rotateY(30deg) rotateZ(0); } to { transform: rotateX(-40deg) rotateY(30deg) rotateZ(360deg); } }
      .core .orb { position:absolute; inset:28%; border-radius:50%;
        background: radial-gradient(circle at 40% 35%, #fff 0%, var(--cc) 30%, rgba(0,0,0,.0) 72%);
        box-shadow: 0 0 40px var(--cc); animation: breathe 2.6s ease-in-out infinite; }
      @keyframes breathe { 50% { transform: scale(1.08); filter: brightness(1.25); } }
      .core .txt { position:absolute; inset:0; display:grid; place-items:center; text-align:center; pointer-events:none; }
      .core .txt b { display:block; font-family:Orbitron,sans-serif; font-size:clamp(14px, 2.2vw, 22px); color:#fff;
        text-shadow:0 0 10px #000, 0 0 6px var(--cc); }
      .core .txt span { font-size:9px; letter-spacing:.2em; color:#fff; text-shadow:0 0 6px #000; }
      .foot { display:grid; grid-template-columns: repeat(3, 1fr); gap:10px; margin-top:6px; }
      .foot > div { padding:8px 10px; border-radius:8px; background:rgba(0,229,255,.04); border:1px solid rgba(0,229,255,.12); }
      .foot .v { font-family:Orbitron,sans-serif; font-size:16px; color:#fff; margin-top:3px; }`;
  }
  _dur(w) { // plus c'est puissant, plus le flux est rapide
    const a = Math.abs(w || 0);
    return Math.max(0.35, 2.6 - Math.log10(Math.max(a, 10)) * 0.6).toFixed(2) + "s";
  }
  render() {
    const c = this._config;
    const hasSolar = !!c.solar;
    const solar = Math.max(0, this.watts(c.solar) ?? 0);
    const grid = this.watts(c.grid);
    // Batterie facultative : `battery_power` (W, positif = décharge, `battery_invert: true` pour l'inverse), `battery_soc` (%).
    const hasBat = !!(c.battery_power || c.battery_soc);
    const bpw = c.battery_power ? this.watts(c.battery_power) : null, bsoc = this.num(c.battery_soc);
    const bw = bpw === null ? null : (c.battery_invert ? -bpw : bpw);
    const home = grid === null ? null : solar + grid + (bw || 0);
    const exporting = grid !== null && grid < -20;
    const autonomy = (hasSolar || hasBat) && home && home > 0 ? Math.min(100, ((hasSolar ? Math.min(solar, home) : 0) + Math.max(bw || 0, 0)) / home * 100) : null;
    const cc = exporting || (autonomy !== null && autonomy > 90) ? SF_C.green : grid !== null && grid > 3000 ? SF_C.amber : SF_C.cyan;

    // Disposition dynamique, selon le nombre d'appareils ET la largeur disponible (le cadre grandit pour garder
    // ~90 px par rang : aucun chevauchement, quel que soit le nombre d'entités).
    //  - écran large  : appareils en 1 à 3 colonnes à droite du cœur ;
    //  - écran étroit (téléphone) : solaire / cœur / réseau en haut, appareils en grille de 3 colonnes dessous.
    // Un appareil à l'arrêt (sous `idle_w`, 20 W par défaut) est masqué (`hide_idle: false` pour tout garder) ;
    // une mesure indisponible reste visible (« — »), c'est une information. La disposition ne porte que sur les visibles.
    const visibles = c.hide_idle === false ? c.devices : c.devices.filter((d) => { const w = this.watts(d.entity); return w === null || Math.abs(w) >= (c.idle_w ?? 20); });
    const hidden = c.devices.length - visibles.length;
    // Plafond d'affichage : au-delà de `max_devices` (8), on garde les plus gourmands, dans l'ordre de la config.
    let devs = visibles, extra = 0;
    const max = Math.max(1, c.max_devices ?? 8);
    if (visibles.length > max) {
      const top = new Set([...visibles].sort((a, b) => Math.abs(this.watts(b.entity) ?? 0) - Math.abs(this.watts(a.entity) ?? 0)).slice(0, max));
      devs = visibles.filter((d) => top.has(d)); extra = visibles.length - max;
    }
    // La batterie est un « appareil » toujours visible, placé en premier, dont le flux va du cœur vers elle (charge) ou inversement.
    if (hasBat) {
      const lvl = bsoc === null ? "mdi:battery" : bsoc >= 95 ? "mdi:battery" : `mdi:battery-${Math.max(10, Math.round(bsoc / 10) * 10)}`;
      devs = [{ __bat: true, name: bsoc === null ? this.t("Batterie") : `${this.t("Batterie")} ${Math.round(bsoc)} %`, icon: lvl, entity: c.battery_soc || c.battery_power,
        color: SF_C.green, w: bw === null ? null : Math.abs(bw), rev: bw !== null && bw > 0 }, ...devs];
    }
    const W = this.getBoundingClientRect().width || 600, NODE = 92;
    const narrow = W < 520;
    let H, pts;
    if (narrow) {
      const cols = devs.length <= 2 ? devs.length || 1 : 3, rows = Math.ceil(devs.length / cols), top = 205;
      H = top + (devs.length ? rows * 92 + 10 : 0) + 10;
      const py = (px) => (px / H) * 100;
      pts = { solar: [17, py(100)], grid: [83, py(100)], core: [50, py(100)] };
      devs.forEach((d, i) => {
        const col = i % cols, row = Math.floor(i / cols);
        pts[`d${i}`] = [cols === 1 ? 50 : cols === 2 ? 30 + col * 40 : 17 + col * 33, py(top + 40 + row * 92)];
      });
    } else {
      const PAD_PX = 44, maxCols = Math.max(1, Math.min(3, Math.floor((W * 0.4) / NODE)));
      const cols = Math.max(1, Math.min(maxCols, Math.ceil(devs.length / 4)));
      const perCol = Array.from({ length: cols }, (_, k) => devs.filter((_, i) => i % cols === k).length);
      H = Math.max(260, Math.max(1, ...perCol) * NODE + PAD_PX * 2 - 20);
      const pad = (PAD_PX / H) * 100, XS = { 1: [88], 2: [72, 91], 3: [63, 78, 93] }[cols];
      // Plus il y a de colonnes d'appareils, plus le noyau (avec solaire et réseau) se décale à gauche et se rapproche
      // de l'injection : [x du noyau, x du réseau] — la place libérée va aux appareils.
      const [cx, gx] = { 1: [50, 16], 2: [42, 14], 3: [35, 12] }[cols];
      pts = { solar: [cx, Math.max(pad, 11)], grid: [gx, 50], core: [cx, 50] };
      devs.forEach((d, i) => {
        const col = i % cols, row = Math.floor(i / cols), m = perCol[col];
        pts[`d${i}`] = [XS[col], m === 1 ? 50 : pad + (row * (100 - 2 * pad)) / (m - 1)];
      });
    }

    // Les coordonnées sont en % du cadre ; le SVG utilise un viewBox 100x56.25 (16/9).
    const Y = (y) => (y * 56.25) / 100;
    const line = (a, b, w, color, rev) => {
      const [x1, y1] = pts[a], [x2, y2] = pts[b];
      const mx = (x1 + x2) / 2, my = (Y(y1) + Y(y2)) / 2;
      const d = narrow && /^d/.test(b) ? `M${x1} ${Y(y1)} C${x1} ${my} ${x2} ${my} ${x2} ${Y(y2)}`
        : `M${x1} ${Y(y1)} C${mx} ${Y(y1)} ${mx} ${Y(y2)} ${x2} ${Y(y2)}`;
      const on = w !== null && Math.abs(w) > 20;
      return `<path class="ln bg" d="${d}" vector-effect="non-scaling-stroke"/>` +
        (on ? `<path class="ln fx ${rev ? "rev" : ""}" d="${d}" stroke="${color}" style="--d:${this._dur(w)};filter:drop-shadow(0 0 2px ${color})" vector-effect="non-scaling-stroke"/>` : "");
    };
    let svg = (hasSolar ? line("solar", "core", solar, SF_C.amber) : "") + line("grid", "core", grid, exporting ? SF_C.green : "#ff7a45", exporting);
    const nodes = [];
    devs.forEach((d, i) => {
      const w = d.__bat ? d.w : this.watts(d.entity);
      svg += line("core", `d${i}`, w, d.color || SF_C.cyan, !!d.rev);
      nodes.push(this._node(pts[`d${i}`], d.name, d.icon, w, d.color || SF_C.cyan, d.entity));
    });
    if (hasSolar) nodes.push(this._node(pts.solar, this.t("Solaire"), "mdi:solar-power-variant", solar, SF_C.amber, c.solar));
    nodes.push(this._node(pts.grid, exporting ? this.t("Injection") : this.t("Réseau"), "mdi:transmission-tower", grid === null ? null : Math.abs(grid), exporting ? SF_C.green : "#ff7a45", c.grid));

    const fossil = this.num(c.fossil), price = this.num(c.price);
    // Pied de page : seulement les indicateurs dont les entités sont configurées.
    const foot = [
      (hasSolar || hasBat) && `<div><div class="lbl">${this.t(hasSolar ? "Autonomie solaire" : "Autonomie")}</div><div class="v" style="color:${cc}">${autonomy === null ? "—" : Math.round(autonomy) + " %"}</div></div>`,
      c.fossil && `<div class="click" data-e="${c.fossil}"><div class="lbl">${this.t("Réseau fossile")}</div><div class="v">${fossil === null ? "—" : fossil.toFixed(0) + " %"}</div></div>`,
      c.price && `<div class="click" data-e="${c.price}"><div class="lbl">${this.t("Coût instantané")}</div><div class="v">${price === null || grid === null ? "—" : ((Math.max(grid, 0) / 1000) * price).toFixed(2) + " €/h"}</div></div>`,
    ].filter(Boolean);
    return this.frame(this.t("Énergie"), `${exporting ? this.t("surplus injecté") : hasSolar && solar > 50 ? this.t("solaire actif") : this.t("réseau")}${hidden ? ` · ${this.t("{n} au repos", { n: hidden })}` : ""}${extra ? ` · ${this.t("+{n} autres", { n: extra })}` : ""}`, `
      <div class="stage" style="${narrow ? `aspect-ratio:auto;height:${H}px` : `min-height:${H}px`}">
        <svg viewBox="0 0 100 56.25" preserveAspectRatio="none">${svg}</svg>
        <div class="core" style="--cc:${cc};left:${pts.core[0]}%;top:${pts.core[1]}%"><div class="r r1"></div><div class="r r2"></div><div class="r r3"></div><div class="orb"></div>
          <div class="txt"><div><b>${this.kw(home)}</b><span>${this.t("MAISON")}</span></div></div></div>
        ${nodes.join("")}
      </div>
      ${foot.length ? `<div class="foot" style="grid-template-columns:repeat(${foot.length},1fr)">${foot.join("")}</div>` : ""}`);
  }
  _node([x, y], name, icon, w, color, id) {
    const idle = w === null || Math.abs(w) < 20;
    return `<div class="node click ${idle ? "idle" : ""}" data-e="${id}" style="left:${x}%;top:${y}%;color:${color}">
      <div class="ic">${this.icon(icon, 22)}</div><div class="n">${this.esc(name)}</div><div class="w">${this.kw(w)}</div></div>`;
  }
  getCardSize() { return 7; }
}

/* ================================================================== CLIMAT */
/*
 * Pièces pilotées : la cible est un input_number,
 * l'interrupteur de pièce appelle `switch_script` s'il est défini (régulation + clim), sinon climate.turn_on / turn_off.
 *
 * type: custom:sf-climate-card
 * mode: input_select.house_mode
 * switch_script: script.my_room_toggle   # facultatif ; sans lui, le bouton marche/arrêt appelle climate.turn_on / turn_off
 * rooms: [{ name, icon, climate, temp, hum, target, regul, window }]
 * extras: [{ label, entity, icon, timer?, stop? }]   # interrupteurs/scripts sous les pièces ; timer = minuteur affiché, stop = entités coupées par un appui
 */
const SF_HVAC = {
  heat: ["Chauffe", "#ff7043", "mdi:fire"], cool: ["Refroidit", "#4fc3f7", "mdi:snowflake"],
  dry: ["Déshumidifie", "#ffca28", "mdi:water-percent"], fan_only: ["Ventile", "#66bb6a", "mdi:fan"],
  heat_cool: ["Auto", "#b388ff", "mdi:autorenew"], off: ["Éteint", SF_C.grey, "mdi:power"],
};
class SfClimateCard extends SfBase {
  defaults() { return { rooms: [], extras: [], switch_script: "", min: 15, max: 30 }; }
  css() {
    return `
      .modes { margin-bottom:14px; }
      .rooms { display:grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap:12px; }
      .room { position:relative; padding:12px 12px 10px; border-radius:12px; overflow:hidden;
        background: linear-gradient(165deg, color-mix(in srgb, var(--hc) 16%, transparent), rgba(3,8,15,.6));
        border:1px solid color-mix(in srgb, var(--hc) 45%, transparent); }
      .room.active { animation: glow 2.4s ease-in-out infinite; }
      @keyframes glow { 50% { box-shadow: 0 0 22px -4px var(--hc), inset 0 0 18px -8px var(--hc); } }
      .rh { display:flex; align-items:center; gap:6px; min-height:28px; font-family:Orbitron,sans-serif; font-size:11px; letter-spacing:.12em; text-transform:uppercase; }
      .rh .fl { margin-left:auto; display:flex; gap:6px; align-items:center; }
      .rh .pw { padding:4px 6px; border-radius:50%; }
      .rh ha-icon, .rh .fl { flex-shrink:0; }
      .dial { position:relative; width:100%; max-width:190px; margin:4px auto 0; }
      .dial svg { width:100%; display:block; }
      .dial .t { position:absolute; left:0; right:0; top:38%; text-align:center; }
      .dial .t b { font-family:Orbitron,sans-serif; font-size:30px; color:#fff; text-shadow:0 0 10px var(--hc); }
      .dial .t small { display:block; font-size:10px; color:${SF_C.dim}; margin-top:2px; letter-spacing:.08em; }
      .ctl { display:grid; grid-template-columns: 36px 1fr 36px; gap:6px; margin-top:4px; align-items:center; }
      .ctl .btn { padding:6px 0; }
      .ctl .tg { text-align:center; font-family:Orbitron,sans-serif; font-size:15px; color:#fff; }
      .ctl .tg small { display:block; font-family:'B612 Mono',monospace; font-size:8px; letter-spacing:.2em; color:${SF_C.dim}; }
      .pw.on { color:var(--hc); border-color:var(--hc); box-shadow:0 0 10px -2px var(--hc); }
      .extras { display:flex; flex-wrap:wrap; gap:8px; margin-top:14px; padding-top:12px; border-top:1px dashed rgba(0,229,255,.18); }`;
  }
  _arc(cx, cy, r, a0, a1) {
    const p = (a) => [cx + r * Math.cos((a * Math.PI) / 180), cy + r * Math.sin((a * Math.PI) / 180)];
    const [x0, y0] = p(a0), [x1, y1] = p(a1);
    return `M${x0.toFixed(2)} ${y0.toFixed(2)} A${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`;
  }
  _room(r) {
    const c = this._config, cl = this.st(r.climate);
    const mode = cl ? cl.state : "off";
    const [mTxt0, hc, mIco] = SF_HVAC[mode] || [this.esc(mode), SF_C.cyan, "mdi:thermostat"];
    const mTxt = SF_HVAC[mode] ? this.t(mTxt0) : mTxt0;
    const action = cl && cl.attributes.hvac_action;
    const active = ["heating", "cooling", "drying", "fan"].includes(action);
    const t = this.num(r.temp) ?? (cl ? cl.attributes.current_temperature : null);
    const tgt = this.num(r.target);
    const hum = this.num(r.hum);
    const A0 = 135, A1 = 405, span = A1 - A0;
    const ang = (v) => A0 + (Math.max(c.min, Math.min(c.max, v)) - c.min) / (c.max - c.min) * span;
    const p = (a, rad) => [60 + rad * Math.cos((a * Math.PI) / 180), 60 + rad * Math.sin((a * Math.PI) / 180)];
    let marks = "";
    for (let v = c.min; v <= c.max; v += 1) {
      const a = ang(v), [x0, y0] = p(a, 47), [x1, y1] = p(a, v % 5 === 0 ? 41 : 44);
      marks += `<line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y1}" stroke="rgba(255,255,255,${v % 5 === 0 ? .35 : .12})" stroke-width="1"/>`;
    }
    let tg = "";
    if (tgt !== null) { const a = ang(tgt), [x, y] = p(a, 53); tg = `<circle cx="${x}" cy="${y}" r="3.2" fill="${SF_C.cyan}" style="filter:drop-shadow(0 0 3px ${SF_C.cyan})"/>`; }
    const win = r.window && this.st(r.window) && this.st(r.window).state === "on";
    const auto = r.regul && this.isOn(r.regul);
    const on = mode !== "off";
    return `<div class="room ${active ? "active" : ""}" style="--hc:${hc}">
      <div class="rh">${this.icon(r.icon || "mdi:home", 16, hc)}<span>${this.esc(r.name)}</span>
        <span class="fl">${win ? `<span class="click" data-e="${r.window}" title="${this.t("fenêtre ouverte")}">${this.icon("mdi:window-open-variant", 16, SF_C.amber)}</span>` : ""}
        ${r.regul ? `<span class="click" data-e="${r.regul}" title="${this.t("régulation auto")}">${this.icon(auto ? "mdi:robot" : "mdi:robot-off", 16, auto ? SF_C.green : SF_C.grey)}</span>` : ""}
        <span class="btn pw ${on ? "on" : ""}" title="${this.t("allumer / éteindre la pièce")}" ${c.switch_script ? this.call(c.switch_script, { regulation: r.regul, climat: r.climate }) : this.call(on ? "climate.turn_off" : "climate.turn_on", { entity_id: r.climate })}>${this.icon("mdi:power", 15)}</span></span></div>
      <div class="dial click" data-e="${r.climate}">
        <svg viewBox="0 0 120 112">${marks}
          <path d="${this._arc(60, 60, 50, A0, A1)}" fill="none" stroke="rgba(255,255,255,.07)" stroke-width="6" stroke-linecap="round"/>
          ${t !== null ? `<path d="${this._arc(60, 60, 50, A0, Math.max(A0 + 1, ang(t)))}" fill="none" stroke="${hc}" stroke-width="6" stroke-linecap="round" style="filter:drop-shadow(0 0 4px ${hc})"/>` : ""}
          ${tg}</svg>
        <div class="t"><b>${t === null ? "—" : Number(t).toFixed(1)}°</b>
          <small>${this.icon(mIco, 11, hc)} ${mode === "off" ? mTxt : active ? mTxt : this.t("En veille")}${hum !== null ? ` · ${Math.round(hum)} %` : ""}</small></div>
      </div>
      <div class="ctl">
        <span class="btn" ${this.call("input_number.decrement", { entity_id: r.target })}>−</span>
        <div class="tg click" data-e="${r.target}"><small>${this.t("CIBLE")}</small>${tgt === null ? "—" : tgt.toFixed(1) + "°"}</div>
        <span class="btn" ${this.call("input_number.increment", { entity_id: r.target })}>+</span>
      </div></div>`;
  }
  render() {
    const c = this._config, m = this.st(c.mode);
    const ICO = [[/^(clim|cool|fr[ií]o|k[üu]hl)/i, "mdi:snowflake"], [/^(d[ée]shu|dry|des|entf)/i, "mdi:water-percent"], [/^(ventil|fan|l[üu]ft)/i, "mdi:fan"], [/^(chauff|heat|calef|calor|heiz)/i, "mdi:fire"], [/^(libre|free|manual|frei)/i, "mdi:hand-back-right"], [/^(absent|away|ausente|abwesend)/i, "mdi:home-export-outline"]];
    const modes = m ? (m.attributes.options || []).map((o) => {
      const txt = o.replace(/^[^\p{L}]+/u, "");
      const ic = (ICO.find(([k]) => k.test(txt)) || [0, "mdi:circle-small"])[1];
      return `<span class="btn ${m.state === o ? "on" : ""}" ${this.call("input_select.select_option", { entity_id: c.mode, option: o })}>${this.icon(ic, 15)}${this.esc(txt)}</span>`;
    }).join("") : "";
    const temps = c.rooms.map((r) => this.num(r.temp)).filter((x) => x !== null);
    const avg = temps.length ? (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1) : null;
    const extras = c.extras.map((x) => {
      const tm = this.timerInfo(x.timer), act = tm.actif && x.stop ? this.call("homeassistant.turn_off", { entity_id: x.stop }, this.t("Arrêter ?")) : this.toggleCall(x.entity);
      return `<span class="btn ${tm.actif || this.isOn(x.entity) ? "on" : ""}" ${act}>${this.icon(x.icon || "mdi:toggle-switch", 15)}${this.esc(x.label)}${tm.actif && tm.reste ? ` · ${tm.reste} min` : ""}</span>`;
    }).join("");
    return this.frame(this.t("Climat"), avg === null ? "" : this.t("{t}° moyen", { t: avg }), `
      ${modes ? `<div class="seg modes"><span class="lbl" style="align-self:center;margin-right:4px">${this.t("Mode maison")}</span>${modes}</div>` : ""}
      <div class="rooms">${c.rooms.map((r) => this._room(r)).join("")}</div>
      ${extras ? `<div class="extras">${extras}</div>` : ""}`);
  }
  getCardSize() { return 8; }
}

/* ================================================================= CONSOLE */
/*
 * Console de commande générique, par groupes.
 *
 * type: custom:sf-console-card
 * title: "Console"
 * groups:
 *   - title: Lumières
 *     items:
 *       - { kind: toggle, entity: light.x, label: Salon, icon: mdi:lightbulb }
 *       - { kind: action, label: Tamisé, icon: mdi:..., service: scene.turn_on, data: {...}, confirm: "Sûr ?" }
 *       - { kind: cover, entity: cover.x, label: Volets }
 *       - { kind: vacuum, entity: vacuum.x, battery: sensor.x, label: Robot }
 *       - { kind: select, entity: input_select.x, label: ... }
 *       - { kind: dimmer, entity: light.x, label: Salon }     # bascule + intensité ±10 %
 *       - { kind: sensor, entity: sensor.x, label: ..., icon: ..., digits: 0 }
 */
class SfConsoleCard extends SfBase {
  defaults() { return { groups: [] }; }
  css() {
    return `
      .groups { display:grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap:14px; }
      .grp h4 { margin:0 0 8px; font-family:Orbitron,sans-serif; font-weight:500; font-size:10px; letter-spacing:.2em;
        color:${SF_C.cyan}; display:flex; align-items:center; gap:6px; }
      .grp h4::after { content:""; flex:1; height:1px; background:linear-gradient(90deg, rgba(0,229,255,.35), transparent); }
      .items { display:grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap:8px; }
      .it { position:relative; display:flex; flex-direction:column; align-items:flex-start; gap:6px; padding:10px;
        border-radius:10px; border:1px solid rgba(0,229,255,.16); background:rgba(0,229,255,.035); min-height:62px; }
      .it .nm { font-size:11px; color:${SF_C.text}; line-height:1.2; }
      .it .sv { font-size:10px; color:${SF_C.dim}; }
      .it.on { border-color:var(--ac, ${SF_C.amber}); background: linear-gradient(160deg, color-mix(in srgb, var(--ac, ${SF_C.amber}) 22%, transparent), transparent);
        box-shadow: 0 0 14px -4px var(--ac, ${SF_C.amber}); }
      .it.on ha-icon { color:var(--ac, ${SF_C.amber}); filter: drop-shadow(0 0 4px var(--ac, ${SF_C.amber})); }
      .it.dead { opacity:.35; }
      .wide { grid-column: 1 / -1; min-height:0; }
      .row { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
      .row .grow { flex:1; min-width:90px; }
      .big { font-family:Orbitron,sans-serif; font-size:18px; color:#fff; }`;
  }
  _item(x) {
    const s = this.st(x.entity), dead = x.entity && !this.ok(x.entity);
    const ic = (n) => this.icon(x.icon || n, 20);
    switch (x.kind) {
      case "toggle": {
        const on = this.isOn(x.entity);
        return `<div class="it ${on ? "on" : ""} ${dead ? "dead" : ""}" style="${x.color ? `--ac:${x.color}` : ""}" ${this.toggleCall(x.entity)}>
          ${ic("mdi:toggle-switch")}<span class="nm">${this.esc(x.label)}</span><span class="sv">${dead ? this.t("muet") : on ? this.t("allumé") : this.t("éteint")}</span></div>`;
      }
      case "action":
        return `<div class="it ${dead ? "dead" : ""}" style="${x.color ? `--ac:${x.color}` : ""}" ${this.call(x.service, x.data, x.confirm)}>
          ${ic("mdi:play")}<span class="nm">${this.esc(x.label)}</span>${x.sub ? `<span class="sv">${this.esc(x.sub)}</span>` : ""}</div>`;
      case "sensor": {
        const v = this.num(x.entity);
        return `<div class="it click ${dead ? "dead" : ""}" data-e="${x.entity}">${ic("mdi:gauge")}<span class="nm">${this.esc(x.label)}</span>
          <span class="big" style="font-size:14px">${v === null ? (s && this.ok(x.entity) ? this.esc(s.state) : "—") : v.toFixed(x.digits ?? 0)}<span class="sv"> ${this.esc(x.unit ?? this.unit(x.entity))}</span></span></div>`;
      }
      case "cover": {
        const pos = s && s.attributes.current_position;
        const txt = !s ? "—" : { open: this.t("ouverts"), closed: this.t("fermés"), opening: this.t("ouverture…"), closing: this.t("fermeture…") }[s.state] || this.esc(s.state);
        return `<div class="it wide"><div class="row"><span class="click" data-e="${x.entity}">${ic("mdi:window-shutter")}</span>
          <div class="grow"><div class="nm">${this.esc(x.label)}</div><div class="sv">${txt}${pos !== undefined && pos !== null ? ` · ${pos} %` : ""}</div></div>
          <span class="btn" ${this.call("cover.open_cover", { entity_id: x.entity })}>${this.icon("mdi:arrow-up", 16)}</span>
          <span class="btn" ${this.call("cover.stop_cover", { entity_id: x.entity })}>${this.icon("mdi:stop", 16)}</span>
          <span class="btn" ${this.call("cover.close_cover", { entity_id: x.entity })}>${this.icon("mdi:arrow-down", 16)}</span></div></div>`;
      }
      case "vacuum": {
        const st = s ? s.state : "unavailable";
        const txt = { docked: this.t("à la base"), cleaning: this.t("nettoie"), returning: this.t("retour base"), paused: this.t("en pause"), idle: this.t("en attente"), error: this.t("ERREUR") }[st] || this.esc(st);
        const bat = this.num(x.battery);
        return `<div class="it wide ${st === "cleaning" ? "on" : ""}" style="--ac:${SF_C.green}"><div class="row">
          <span class="click" data-e="${x.entity}">${ic("mdi:robot-vacuum")}</span>
          <div class="grow"><div class="nm">${this.esc(x.label || "Aspirateur")}</div><div class="sv" style="${st === "error" ? `color:${SF_C.red}` : ""}">${txt}${bat !== null ? ` · ${Math.round(bat)} %` : ""}</div></div>
          ${st === "cleaning" ? `<span class="btn" ${this.call("vacuum.pause", { entity_id: x.entity })}>${this.icon("mdi:pause", 16)}</span>`
            : `<span class="btn" ${this.call("vacuum.start", { entity_id: x.entity })}>${this.icon("mdi:play", 16)}</span>`}
          <span class="btn" ${this.call("vacuum.return_to_base", { entity_id: x.entity })}>${this.icon("mdi:home-import-outline", 16)}</span></div>
          ${(x.shortcuts || []).length ? `<div class="row" style="margin-top:6px">${x.shortcuts.filter((b) => this.st(b.entity) && this.st(b.entity).state !== "unavailable").map((b) =>
            `<span class="btn" ${this.call("button.press", { entity_id: b.entity })}>${this.icon(b.icon || "mdi:map-marker-path", 14)}${this.esc(b.label)}</span>`).join("")}</div>` : ""}</div>`;
      }
      case "dimmer": {
        // Ampoule : bascule + variation d'intensité par pas de 10 % (couleur / température : fiche de l'entité).
        const on = this.isOn(x.entity), b = s && s.attributes.brightness;
        const pct = on && typeof b === "number" ? Math.round(b / 2.55) : null;
        const step = (d) => this.call("light.turn_on", { entity_id: x.entity, brightness_step_pct: d });
        return `<div class="it wide ${on ? "on" : ""} ${dead ? "dead" : ""}" style="${x.color ? `--ac:${x.color}` : ""}"><div class="row">
          <span ${this.toggleCall(x.entity)}>${ic("mdi:lightbulb")}</span>
          <div class="grow click" data-e="${x.entity}"><div class="nm">${this.esc(x.label)}</div><div class="sv">${dead ? this.t("muet") : on ? (pct === null ? this.t("allumé") : pct + " %") : this.t("éteint")}</div></div>
          <span class="btn" ${dead ? "" : step(-10)}>−</span><span class="btn" ${dead ? "" : step(10)}>+</span></div></div>`;
      }
      case "stepper": {
        // input_number : increment/decrement ; number : set_value borné au pas déclaré.
        const v = this.num(x.entity), a = (s && s.attributes) || {}, step = a.step || 1;
        const dom = (x.entity || "").split(".")[0];
        const go = (dir) => dom === "input_number"
          ? this.call(`input_number.${dir > 0 ? "increment" : "decrement"}`, { entity_id: x.entity })
          : this.call("number.set_value", { entity_id: x.entity, value: Math.max(a.min ?? -Infinity, Math.min(a.max ?? Infinity, (v ?? 0) + dir * step)) });
        return `<div class="it wide ${dead ? "dead" : ""}"><div class="row"><span class="click" data-e="${x.entity}">${ic("mdi:tune-vertical")}</span>
          <div class="grow"><div class="nm">${this.esc(x.label)}</div></div>
          <span class="btn" ${v === null ? "" : go(-1)}>−</span>
          <span class="big click" data-e="${x.entity}" style="min-width:64px;text-align:center;font-size:15px">${v === null ? "—" : v.toFixed(x.digits ?? (step < 1 ? 1 : 0))}<span class="sv"> ${this.esc(x.unit ?? this.unit(x.entity))}</span></span>
          <span class="btn" ${v === null ? "" : go(1)}>+</span></div></div>`;
      }
      case "select": {
        const opts = (s && s.attributes.options) || [];
        return `<div class="it wide"><div class="nm">${this.esc(x.label)}</div><div class="seg">${opts.map((o) =>
          `<span class="btn ${s.state === o ? "on" : ""}" ${this.call(`${x.entity.split(".")[0]}.select_option`, { entity_id: x.entity, option: o })}>${this.esc((x.labels && x.labels[o]) || o)}</span>`).join("")}</div></div>`;
      }
      default: return "";
    }
  }
  render() {
    const c = this._config;
    const body = c.groups.map((g) => `<div class="grp" style="${g.span ? `grid-column:span ${g.span}` : ""}"><h4>${g.icon ? this.icon(g.icon, 14) : ""}${this.esc(g.title)}</h4>
      <div class="items">${(g.items || []).map((x) => this._item(x)).join("")}</div></div>`).join("");
    return this.frame(this.esc(c.title || this.t("Commandes")), c.subtitle ? this.esc(c.subtitle) : "", `<div class="groups">${body}</div>`);
  }
  getCardSize() { return 6; }
}

/* ================================================================= CAMÉRAS */
/*
 * Mosaïque de caméras avec réticule. Image fixe rafraîchie toutes les `refresh`
 * secondes (léger) ; un appui ouvre la fiche HA de la caméra, avec le flux en direct.
 *
 * type: custom:sf-camera-card
 * refresh: 5
 * cameras: [{ entity, name, motion, persons, review }]
 */
class SfCameraCard extends SfBase {
  defaults() { return { cameras: [], refresh: 5 }; }
  connectedCallback() {
    this._timer = setInterval(() => this._refresh(), (this._config ? this._config.refresh : 5) * 1000);
  }
  disconnectedCallback() { clearInterval(this._timer); }
  afterRender() { this._refresh(); }
  _refresh() {
    if (!this.shadowRoot || document.hidden) return;
    this.shadowRoot.querySelectorAll("img[data-cam]").forEach((img) => {
      const s = this.st(img.dataset.cam);
      if (!s || !s.attributes.entity_picture) return;
      const url = `${s.attributes.entity_picture}&_t=${Date.now()}`;
      const pre = new Image();
      pre.onload = () => { img.src = url; img.classList.add("ok"); };
      pre.src = url;
    });
  }
  css() {
    return `
      .cams { display:grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap:12px; }
      .cam { position:relative; aspect-ratio:16/9; border-radius:10px; overflow:hidden; background:#000;
        border:1px solid rgba(0,229,255,.25); }
      .cam img { width:100%; height:100%; object-fit:cover; display:block; opacity:0; transition:opacity .4s; filter:saturate(.85) contrast(1.05); }
      .cam img.ok { opacity:1; }
      .cam::before { content:""; position:absolute; inset:0; z-index:1; pointer-events:none;
        background: repeating-linear-gradient(0deg, rgba(0,0,0,.18) 0 1px, transparent 1px 3px),
                    radial-gradient(ellipse at center, transparent 60%, rgba(0,0,0,.55)); }
      .ov { position:absolute; inset:0; z-index:2; pointer-events:none; padding:10px 12px; display:flex; flex-direction:column; justify-content:space-between; }
      .ov .t, .ov .b { display:flex; justify-content:space-between; align-items:center; gap:8px; }
      .tag { font-family:Orbitron,sans-serif; font-size:11px; letter-spacing:.18em; color:#fff; text-shadow:0 0 6px #000, 0 0 8px ${SF_C.cyan}; }
      .rec { font-size:10px; color:${SF_C.red}; letter-spacing:.14em; display:flex; align-items:center; gap:5px; text-shadow:0 0 4px #000; }
      .rec::before { content:""; width:8px; height:8px; border-radius:50%; background:${SF_C.red}; box-shadow:0 0 8px ${SF_C.red}; animation: blink 1s infinite; }
      .pill { font-size:10px; padding:3px 8px; border-radius:10px; background:rgba(0,0,0,.55); border:1px solid rgba(0,229,255,.35); color:${SF_C.text}; }
      .pill.hot { border-color:${SF_C.amber}; color:${SF_C.amber}; }
      .pill.red { border-color:${SF_C.red}; color:${SF_C.red}; }
      .ret { position:absolute; left:50%; top:50%; width:46px; height:46px; transform:translate(-50%,-50%); z-index:2; pointer-events:none; opacity:.55; }
      .ret::before, .ret::after { content:""; position:absolute; background:${SF_C.cyan}; }
      .ret::before { left:50%; top:0; bottom:0; width:1px; } .ret::after { top:50%; left:0; right:0; height:1px; }
      .cam .c { z-index:3; }
      .nofeed { position:absolute; inset:0; display:grid; place-items:center; color:${SF_C.grey}; font-size:11px; letter-spacing:.2em; }`;
  }
  render() {
    const cams = this._config.cameras.map((k) => {
      const s = this.st(k.entity);
      const motion = k.motion && this.st(k.motion) && this.st(k.motion).state === "on";
      const pc = this.num(k.persons);
      const rv = k.review && this.ok(k.review) ? this.st(k.review).state : null;
      return `<div class="cam click" data-e="${k.entity}">
        <div class="nofeed">${s ? this.t("chargement…") : this.t("caméra indisponible")}</div>
        ${s ? `<img data-cam="${k.entity}" alt="">` : ""}
        <i class="c tl"></i><i class="c tr"></i><i class="c bl"></i><i class="c br"></i><div class="ret"></div>
        <div class="ov"><div class="t"><span class="tag">${this.esc(k.name)}</span>${s && s.state === "recording" ? `<span class="rec">REC</span>` : `<span class="pill">${s ? this.esc(s.state) : "—"}</span>`}</div>
          <div class="b"><span class="pill ${motion ? "hot" : ""}">${motion ? this.t("MOUVEMENT") : this.t("calme")}</span>
            ${pc !== null ? `<span class="pill ${pc > 0 ? "hot" : ""}">${this.t("{n} personne(s)", { n: pc })}</span>` : ""}
            ${rv && rv !== "NONE" ? `<span class="pill ${rv === "ALERT" ? "red" : "hot"}">${rv === "ALERT" ? this.t("alerte Frigate") : this.t("détection")}</span>` : ""}</div></div></div>`;
    }).join("");
    return this.frame(this.t("Caméras"), this.t("rafraîchi toutes les {n} s · appui = direct", { n: this._config.refresh }), `<div class="cams">${cams}</div>`);
  }
  getCardSize() { return 6; }
}

/* =============================================================== CONSIGNES */
/*
 * Matrice de consignes : une ligne par pièce, une colonne par programme.
 *
 * type: custom:sf-setpoints-card
 * columns: [{ label, color }]
 * rows: [{ name, icon, entities: [input_number.x, ...] }]   # dans l'ordre des colonnes
 */
class SfSetpointsCard extends SfBase {
  defaults() { return { columns: [], rows: [] }; }
  css() {
    return `
      table { width:100%; border-collapse:separate; border-spacing:0 6px; }
      th { font-family:Orbitron,sans-serif; font-weight:500; font-size:10px; letter-spacing:.16em; text-align:center; padding:4px; }
      td { padding:6px 4px; background:rgba(0,229,255,.03); border-top:1px solid rgba(0,229,255,.1); border-bottom:1px solid rgba(0,229,255,.1); }
      td:first-child { border-left:1px solid rgba(0,229,255,.1); border-radius:8px 0 0 8px; padding-left:10px; white-space:nowrap; }
      td:last-child { border-right:1px solid rgba(0,229,255,.1); border-radius:0 8px 8px 0; }
      .st { display:flex; align-items:center; justify-content:center; gap:4px; }
      .st .btn { padding:3px 8px; }
      .st b { font-family:Orbitron,sans-serif; font-size:14px; min-width:44px; text-align:center; color:#fff; }
      @media (max-width: 640px) { .st .btn { display:none; } }`;
  }
  render() {
    const c = this._config;
    const head = `<tr><th></th>${c.columns.map((k) => `<th style="color:${k.color || SF_C.cyan}">${this.esc(k.label)}</th>`).join("")}</tr>`;
    const rows = c.rows.map((r) => `<tr><td>${this.icon(r.icon || "mdi:home", 15, SF_C.dim)} ${this.esc(r.name)}</td>${r.entities.map((id, i) => {
      const v = this.num(id), col = (c.columns[i] || {}).color || SF_C.cyan;
      return `<td><div class="st"><span class="btn" ${this.call("input_number.decrement", { entity_id: id })}>−</span>
        <b class="click" data-e="${id}" style="text-shadow:0 0 8px ${col}">${v === null ? "—" : v.toFixed(1) + "°"}</b>
        <span class="btn" ${this.call("input_number.increment", { entity_id: id })}>+</span></div></td>`;
    }).join("")}</tr>`).join("");
    return this.frame(this.esc(c.title || this.t("Consignes")), this.esc(c.subtitle || ""), `<table>${head}${rows}</table>`);
  }
  getCardSize() { return 6; }
}

/* ================================================================== BILAN */
/*
 * Bilan de consommation par appareil sur une période choisie (input_select).
 *
 * type: custom:sf-ledger-card
 * period: input_select.x    total_cost: sensor.x   solar_fraction: sensor.x   avg_price: sensor.x
 * devices: [{ name, icon, total, edf, solar, cost }]
 */
class SfLedgerCard extends SfBase {
  defaults() { return { devices: [] }; }
  css() {
    return `
      .kpis { display:grid; grid-template-columns: repeat(3, 1fr); gap:10px; margin:12px 0 16px; }
      .kpi { padding:10px 12px; border-radius:10px; background:rgba(0,229,255,.04); border:1px solid rgba(0,229,255,.14); }
      .kpi .v { font-family:Orbitron,sans-serif; font-size:22px; color:#fff; margin-top:4px; }
      .dev { display:grid; grid-template-columns: 150px 1fr 90px; gap:12px; align-items:center; padding:8px 0;
        border-bottom:1px solid rgba(0,229,255,.08); }
      @media (max-width: 560px) { .dev { grid-template-columns: 1fr; gap:6px; } }
      .bar { height:12px; border-radius:6px; background:rgba(255,255,255,.06); overflow:hidden; display:flex; }
      .bar i { display:block; height:100%; transition: width 1s; }
      .legend { display:flex; gap:14px; font-size:10px; color:${SF_C.dim}; margin-top:10px; }
      .legend i { display:inline-block; width:10px; height:10px; border-radius:2px; margin-right:5px; vertical-align:-1px; }`;
  }
  render() {
    const c = this._config, p = this.st(c.period);
    const seg = p ? (p.attributes.options || []).map((o) => `<span class="btn ${p.state === o ? "on" : ""}" ${this.call("input_select.select_option", { entity_id: c.period, option: o })}>${this.esc(o)}</span>`).join("") : "";
    const max = Math.max(1, ...c.devices.map((d) => this.num(d.total) || 0));
    const devs = c.devices.map((d) => {
      const tot = this.num(d.total), e = this.num(d.edf) || 0, s = this.num(d.solar) || 0, cost = this.num(d.cost);
      return `<div class="dev click" data-e="${d.total}"><div>${this.icon(d.icon || "mdi:flash", 16, SF_C.cyan)} ${this.esc(d.name)}
          <div class="lbl" style="margin-top:2px;text-transform:none">${tot === null ? "—" : tot.toFixed(1) + " kWh"}</div></div>
        <div class="bar"><i style="width:${(s / max) * 100}%;background:${SF_C.amber};box-shadow:0 0 8px ${SF_C.amber}"></i><i style="width:${(e / max) * 100}%;background:#ff7a45"></i></div>
        <div class="val" style="text-align:right">${cost === null ? "—" : cost.toFixed(2) + " €"}</div></div>`;
    }).join("");
    const fr = this.num(c.solar_fraction), tc = this.num(c.total_cost), ap = this.num(c.avg_price);
    const hasSolar = !!c.solar_fraction || c.devices.some((d) => d.solar);
    const kp = [[c.total_cost, "Coût réseau", tc === null ? "—" : tc.toFixed(2) + " €", ""], [c.solar_fraction, "Part solaire", fr === null ? "—" : Math.round(fr) + " %", `color:${SF_C.amber}`],
      [c.avg_price, "Prix moyen", ap === null ? "—" : ap.toFixed(3) + " €", ""]].filter((k) => k[0]);
    return this.frame(this.t("Bilan énergétique"), p ? this.esc(p.state) : "", `
      <div class="seg">${seg}</div>
      <div class="kpis" style="grid-template-columns:repeat(${Math.max(1, kp.length)},1fr)">${kp.map((k) => `<div class="kpi click" data-e="${k[0]}"><div class="lbl">${this.t(k[1])}</div><div class="v" style="${k[3]}">${k[2]}</div></div>`).join("")}
      </div>${devs}
      <div class="legend">${hasSolar ? `<span><i style="background:${SF_C.amber}"></i>${this.t("solaire")}</span>` : ""}<span><i style="background:#ff7a45"></i>${this.t("Réseau")}</span><span>${this.t("estimations")}</span></div>`);
  }
  getCardSize() { return 6; }
}

/* ================================================================ CELLULES */
/*
 * Batteries de tous les capteurs (device_class battery), découvertes automatiquement,
 * les plus faibles d'abord.
 *
 * type: custom:sf-cells-card
 * warn: 30   crit: 15   limit: 16   exclude: [sensor.x, ...]   include_pattern: "" (regex facultative)
 */
class SfCellsCard extends SfBase {
  defaults() { return { warn: 30, crit: 15, limit: 16, exclude: [] }; }
  css() {
    return `
      .cells { display:grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap:8px; }
      .cell { display:grid; grid-template-columns: 26px 1fr; gap:8px; align-items:center; padding:7px 9px; border-radius:8px;
        background:rgba(0,229,255,.03); border:1px solid rgba(0,229,255,.1); }
      .bat { position:relative; width:14px; height:24px; border:1.5px solid currentColor; border-radius:3px; margin:0 auto; }
      .bat::before { content:""; position:absolute; top:-4px; left:3px; width:5px; height:3px; background:currentColor; border-radius:1px 1px 0 0; }
      .bat i { position:absolute; left:1.5px; right:1.5px; bottom:1.5px; border-radius:1px; background:currentColor; box-shadow:0 0 6px currentColor; }
      .cell > div:last-child { min-width:0; }
      .cell .nm { font-size:10.5px; line-height:1.2; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
      .cell .pc { font-family:Orbitron,sans-serif; font-size:13px; }`;
  }
  render() {
    const c = this._config, re = c.include_pattern ? new RegExp(c.include_pattern) : null, ex = c.exclude_pattern ? new RegExp(c.exclude_pattern) : null;
    const list = Object.values(this._hass.states).filter((s) => s.entity_id.startsWith("sensor.")
      && s.attributes.device_class === "battery" && !c.exclude.includes(s.entity_id) && (!re || re.test(s.entity_id)) && (!ex || !ex.test(s.entity_id))
      && !isNaN(parseFloat(s.state))).map((s) => [s, parseFloat(s.state)]).sort((a, b) => a[1] - b[1]);
    const low = list.filter(([, v]) => v <= c.warn).length;
    const cells = list.slice(0, c.limit).map(([s, v]) => {
      const col = v <= c.crit ? SF_C.red : v <= c.warn ? SF_C.amber : SF_C.green;
      const nm = (s.attributes.friendly_name || s.entity_id).replace(/\s*(Batterie|Battery( level)?|Battery Level)$/i, "");
      return `<div class="cell click" data-e="${s.entity_id}" style="color:${col}"><div class="bat"><i style="height:calc(${Math.max(4, Math.min(100, v))}% - 3px)"></i></div>
        <div><div class="nm" style="color:${SF_C.text}" title="${this.esc(nm)}">${this.esc(nm)}</div><div class="pc">${Math.round(v)} %</div></div></div>`;
    }).join("");
    return this.frame(this.t("Batteries des capteurs"), this.t("{n} capteurs · {m} à remplacer bientôt", { n: list.length, m: low }), `<div class="cells">${cells}</div>`);
  }
  getCardSize() { return 5; }
}

/* ================================================================== POPUPS */
/*
 * Lanceur de popups (pensé pour le téléphone) : une grille de tuiles résumées ; un
 * appui ouvre la carte complète dans un panneau qui monte du bas de l'écran.
 * Le panneau est attaché à <body> (hors de la grille HA, dont le confinement CSS
 * casserait un position:fixed) et reçoit `hass` à chaque mise à jour.
 * Le bouton retour du téléphone ferme le panneau (une entrée d'historique #hash
 * est ajoutée à l'ouverture) ; un lien vers #hash ouvre directement le panneau.
 *
 * type: custom:sf-launcher-card
 * columns: 2
 * tiles:
 *   - name: Climat
 *     icon: mdi:thermostat
 *     color: "#ff7043"
 *     hash: climat
 *     summary: climate | vehicles | commands | cameras | energy | machines   (calculé depuis `card`)
 *     users: [id, ...]          # facultatif : tuile visible seulement pour ces utilisateurs
 *     card: { type: custom:sf-climate-card, ... }
 */
const SF_POP_CSS = `
  .back { position:fixed; inset:0; z-index:9998; background:rgba(1,4,9,.66); backdrop-filter:blur(6px);
    -webkit-backdrop-filter:blur(6px); opacity:0; transition:opacity .25s; }
  .sheet { position:fixed; z-index:9999; left:0; right:0; bottom:0; max-height:92vh; display:flex; flex-direction:column;
    background: linear-gradient(180deg, #071426 0%, #03080f 100%); border-top:1px solid rgba(0,229,255,.45);
    border-radius:22px 22px 0 0; box-shadow:0 -10px 40px rgba(0,229,255,.18);
    transform:translateY(105%); transition:transform .32s cubic-bezier(.2,.9,.25,1);
    padding-bottom: env(safe-area-inset-bottom); }
  @media (min-width: 900px) { .sheet { left:50%; right:auto; width:860px; margin-left:-430px; bottom:4vh; border-radius:22px;
    border:1px solid rgba(0,229,255,.45); max-height:88vh; } }
  .open .back { opacity:1; } .open .sheet { transform:none; }
  .grab { width:44px; height:5px; border-radius:3px; background:rgba(0,229,255,.45); margin:9px auto 2px; }
  .bar { display:flex; align-items:center; gap:10px; padding:0 14px 6px; color:${SF_C.cyan};
    font:700 12px Orbitron, sans-serif; letter-spacing:.2em; text-transform:uppercase; }
  .bar button { margin-left:auto; width:36px; height:36px; border-radius:50%; border:1px solid rgba(0,229,255,.35);
    background:rgba(0,229,255,.08); color:${SF_C.text}; font-size:18px; cursor:pointer; }
  .body { overflow-y:auto; -webkit-overflow-scrolling:touch; padding:0 10px 14px; overscroll-behavior:contain; }
`;
class SfLauncherCard extends SfBase {
  defaults() { return { tiles: [], columns: 2 }; }
  connectedCallback() {
    this._onPop = () => {
      const h = location.hash.slice(1);
      if (this._pop && h !== this._pop.hash) this._close(false);
      else if (!this._pop && h && this._hass) { const t = this._tiles().find((x) => x.hash === h); if (t) this._open(t, false); }
    };
    window.addEventListener("popstate", this._onPop);
    window.addEventListener("hashchange", this._onPop);
    setTimeout(this._onPop, 400);  // lien direct …/accueil#climat
  }
  disconnectedCallback() {
    window.removeEventListener("popstate", this._onPop);
    window.removeEventListener("hashchange", this._onPop);
    this._close(false);
  }
  set hass(hass) {
    super.hass = hass;
    if (this._pop) this._pop.card.hass = hass;
  }
  get hass() { return this._hass; }
  _tiles() {
    const uid = this._hass && this._hass.user && this._hass.user.id;
    return this._config.tiles.filter((t) => !t.users || !uid || t.users.includes(uid));
  }
  css() {
    return `
      .tiles { display:grid; grid-template-columns: repeat(var(--cols), 1fr); gap:10px; font-family:'B612 Mono', ui-monospace, monospace; }
      .tile { position:relative; padding:12px 12px 11px; border-radius:14px; cursor:pointer; overflow:hidden;
        background: linear-gradient(155deg, color-mix(in srgb, var(--tc) 18%, transparent), rgba(3,8,15,.8));
        border:1px solid color-mix(in srgb, var(--tc) 45%, transparent); -webkit-tap-highlight-color:transparent;
        transition: transform .12s; }
      .tile:active { transform:scale(.97); }
      .tile .top { display:flex; align-items:center; gap:7px; font:700 10.5px Orbitron,sans-serif; letter-spacing:.14em;
        text-transform:uppercase; color:var(--tc); }
      .tile .top .go { margin-left:auto; opacity:.6; }
      .tile .main { font:500 21px Orbitron,sans-serif; color:#fff; margin-top:8px; text-shadow:0 0 10px var(--tc); }
      .tile .sub { font-size:10.5px; color:${SF_C.dim}; margin-top:4px; line-height:1.35; }
      .tile.hot { animation: tglow 2.2s ease-in-out infinite; }
      @keyframes tglow { 50% { box-shadow:0 0 18px -4px var(--tc); } }`;
  }
  // Résumé d'une tuile, calculé depuis la config de la carte qu'elle ouvre.
  _sum(t) {
    const c = t.card || {}, n = (id) => this.num(id);
    switch (t.summary) {
      case "climate": {
        const temps = (c.rooms || []).map((r) => n(r.temp)).filter((x) => x !== null);
        const act = (c.rooms || []).filter((r) => { const s = this.st(r.climate); return s && ["heating", "cooling", "drying"].includes(s.attributes.hvac_action); }).length;
        const m = this.st(c.mode);
        return { main: temps.length ? this.t("{t}° moy.", { t: (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1) }) : "—",
          sub: `${m ? this.esc(m.state.replace(/^[^\p{L}]+/u, "")) : ""} · ${act ? this.t("{n} pièce(s) active(s)", { n: act }) : this.t("au repos")}`, hot: act > 0 };
      }
      case "room": {
        const r = (c.rooms || [])[0] || {}, t = n(r.temp), h = n(r.hum), cl = this.st(r.climate);
        const act = cl && ["heating", "cooling", "drying", "fan"].includes(cl.attributes.hvac_action);
        const lbl = cl && SF_HVAC[cl.state] ? this.t(SF_HVAC[cl.state][0]) : "";
        return { main: t === null ? "—" : t.toFixed(1) + "°",
          sub: `${h === null ? "" : Math.round(h) + " % · "}${act ? lbl : cl && cl.state !== "off" ? this.t("En veille") : this.t("Éteint")}`, hot: !!act };
      }
      case "vehicles": {
        const cars = (c.cars || []).map((x) => `${this.esc(x.name)} ${n(x.soc) === null ? "—" : Math.round(n(x.soc)) + " %"}`).join(" · ");
        const ch = c.charger || {}, charging = this.isOn(ch.charging), con = this.isOn(ch.connected);
        const m = this.st(c.mode);
        return { main: charging ? this.kw(this.watts(ch.power)) : con ? this.t("Branchée") : this.t("Libre"),
          sub: `${cars}${m ? `<br>${this.t("Mode {m}", { m: this.esc(m.state) })}` : ""}`, hot: charging };
      }
      case "commands": {
        const items = (c.groups || []).flatMap((g) => g.items || []);
        const lights = items.filter((x) => x.kind === "toggle" && /^(light|switch)\./.test(x.entity || ""));
        const on = lights.filter((x) => this.isOn(x.entity)).length;
        const cov = items.find((x) => x.kind === "cover"), cs = cov && this.st(cov.entity);
        return { main: `${on} / ${lights.length}`, sub: `${this.t("lumières allumées")}${cs ? `<br>${this.t("volets {s}", { s: ({ open: this.t("ouverts"), closed: this.t("fermés") })[cs.state] || this.esc(cs.state) })}` : ""}`, hot: false };
      }
      case "cameras": {
        const cams = c.cameras || [];
        const mv = cams.filter((k) => this.isOn(k.motion)).length;
        return { main: mv ? this.t("{n} mouvement(s)", { n: mv }) : this.t("Calme"), sub: this.t("{n} caméras · appui = images", { n: cams.length }), hot: mv > 0 };
      }
      case "energy": {
        const solar = Math.max(0, this.watts(c.solar) ?? 0), grid = this.watts(c.grid);
        return { main: this.kw(grid === null ? null : solar + grid), sub: `${this.t("consommation maison")}${c.solar ? `<br>${this.t("solaire {w}", { w: this.kw(solar) })}` : ""}`, hot: false };
      }
      case "battery": {
        const soc = n(c.soc), w = c.power ? this.watts(c.power) : null, bw = w === null ? null : (c.invert ? -w : w);
        return { main: soc === null ? "—" : `${Math.round(soc)} %`, sub: bw === null ? "" : Math.abs(bw) < 20 ? this.t("En veille") : bw > 0 ? `${this.t("Décharge")} · ${this.kw(bw)}` : `${this.t("Charge")} · ${this.kw(-bw)}`, hot: bw !== null && Math.abs(bw) >= 20 };
      }
      case "machines": {
        const tiles = c.tiles || [];
        const bad = tiles.filter((x) => !this.ok(x.entity)).length;
        const first = tiles[0], v = first ? n(first.entity) : null;
        return { main: v === null ? "—" : `${v.toFixed(first.digits ?? 1)}${this.esc(first.unit ?? this.unit(first.entity))}`,
          sub: `${first ? this.esc(first.label) : ""}${bad ? ` · ${this.t("{n} sans réponse", { n: bad })}` : ""}`, hot: false };
      }
      default: return { main: "", sub: this.esc(t.sub || ""), hot: false };
    }
  }
  render() {
    const tiles = this._tiles().map((t, i) => {
      const s = this._sum(t);
      return `<div class="tile ${s.hot ? "hot" : ""}" data-i="${i}" style="--tc:${t.color || SF_C.cyan}">
        <div class="top">${this.icon(t.icon || "mdi:open-in-new", 16)}${this.esc(t.name)}<span class="go">${this.icon("mdi:chevron-up", 16)}</span></div>
        <div class="main">${s.main}</div><div class="sub">${s.sub}</div></div>`;
    }).join("");
    return `<div class="tiles" style="--cols:${Number(this._config.columns) || 2}">${tiles}</div>`;
  }
  afterRender() {
    this.shadowRoot.querySelectorAll(".tile").forEach((el) => el.addEventListener("click", () => {
      const t = this._tiles()[Number(el.dataset.i)]; if (t) this._open(t, true);
    }));
  }
  _open(t, push) {
    if (this._pop) this._close(false);
    const host = document.createElement("div");
    const root = host.attachShadow({ mode: "open" });
    root.innerHTML = `<style>${SF_POP_CSS}</style><div class="wrap"><div class="back"></div><div class="sheet">
      <div class="grab"></div><div class="bar"><button aria-label="${this.t("Fermer")}">✕</button></div><div class="body"></div></div></div>`;
    const card = document.createElement(String(t.card && t.card.type || "").replace("custom:", ""));
    try { card.setConfig(t.card); } catch (e) { card.textContent = `Erreur : ${e.message}`; }
    card.hass = this._hass;
    root.querySelector(".body").appendChild(card);
    const close = () => this._close(true);
    root.querySelector(".back").addEventListener("click", close);
    root.querySelector(".bar button").addEventListener("click", close);
    this._esc = (ev) => { if (ev.key === "Escape") close(); };
    document.addEventListener("keydown", this._esc);
    document.body.appendChild(host);
    this._pop = { host, card, hash: t.hash || "" };
    requestAnimationFrame(() => requestAnimationFrame(() => root.querySelector(".wrap").classList.add("open")));
    if (push && t.hash && location.hash !== `#${t.hash}`) history.pushState({ sfPopup: t.hash }, "", `${location.pathname}${location.search}#${t.hash}`);
  }
  _close(viaUi) {
    const p = this._pop; if (!p) return;
    this._pop = null;
    document.removeEventListener("keydown", this._esc);
    p.host.shadowRoot.querySelector(".wrap").classList.remove("open");
    setTimeout(() => p.host.remove(), 330);
    // Fermé à la main : on retire l'entrée #hash ajoutée à l'ouverture.
    if (viaUi && p.hash && location.hash === `#${p.hash}`) history.back();
  }
  getCardSize() { return 4; }
}

/* ============================================================== BATTERIE */
/*
 * Batterie domestique : niveau, sens et puissance du flux, autonomie estimée, énergie du jour, mode.
 * Tout est facultatif : seul ce qui est configuré s'affiche, et sans `soc` ni `power` la carte disparaît.
 *
 * type: custom:sf-battery-card
 * soc: sensor.x (%)     power: sensor.x (W, positif = décharge ; `invert: true` si c'est l'inverse)
 * capacity_kwh: 10      charged_today: sensor.x (kWh)   discharged_today: sensor.x (kWh)
 * mode: select.x | input_select.x     temperature: sensor.x     health: sensor.x (%)     cycles: sensor.x
 */
class SfBatteryCard extends SfBase {
  defaults() { return { invert: false }; }
  _has() { const c = this._config; return !!(c.soc || c.power); }
  css() {
    const none = this._has() ? "" : ":host{display:none}";
    return `${none}
      .gauge { display:grid; grid-template-columns: 132px 1fr; gap:14px; align-items:center; }
      @media (max-width: 380px) { .gauge { grid-template-columns: 1fr; justify-items:center; text-align:center; } }
      .ring { position:relative; width:132px; height:132px; }
      .ring svg { width:100%; height:100%; transform:rotate(-90deg); }
      .ring .t { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; }
      .ring .t b { font-family:Orbitron,sans-serif; font-size:28px; color:#fff; }
      .ring .t small { font-size:9px; letter-spacing:.14em; color:${SF_C.dim}; }
      .st { font-family:Orbitron,sans-serif; font-size:15px; letter-spacing:.1em; }
      .sub { margin-top:4px; font-size:11px; color:${SF_C.dim}; line-height:1.5; }
      .stats { display:grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap:8px; margin-top:14px; }
      .stats > div { padding:8px 10px; border-radius:8px; background:rgba(0,229,255,.04); border:1px solid rgba(0,229,255,.12); }
      .stats .v { font-family:Orbitron,sans-serif; font-size:15px; color:#fff; margin-top:3px; }
      .modes { margin-top:14px; } .modes .lbl { margin-bottom:6px; }`;
  }
  render() {
    if (!this._has()) return "";
    const c = this._config, soc = this.num(c.soc);
    const w = c.power ? this.watts(c.power) : null, bw = w === null ? null : (c.invert ? -w : w);   // + = décharge
    const idle = bw === null || Math.abs(bw) < 20;
    const col = soc === null ? SF_C.grey : soc <= 15 ? SF_C.red : soc <= 30 ? SF_C.amber : SF_C.green;
    const state = idle ? this.t("En veille") : bw > 0 ? this.t("Décharge") : this.t("Charge");
    const R = 56, C = 2 * Math.PI * R, pct = soc === null ? 0 : Math.max(0, Math.min(100, soc));
    // Autonomie estimée : seulement si la capacité est connue et que ça circule.
    let eta = "";
    const cap = Number(c.capacity_kwh);
    if (cap > 0 && soc !== null && !idle) {
      const kwhLeft = bw > 0 ? (cap * pct) / 100 : (cap * (100 - pct)) / 100, h = kwhLeft / (Math.abs(bw) / 1000);
      if (isFinite(h) && h < 100) eta = this.t(bw > 0 ? "vide dans {h}h{m}" : "pleine dans {h}h{m}", { h: Math.floor(h), m: String(Math.round((h % 1) * 60)).padStart(2, "0") });
    }
    const stat = (id, label, unit, digits) => { if (!id) return ""; const n = this.num(id); return `<div class="click" data-e="${id}"><div class="lbl">${this.t(label)}</div><div class="v">${n === null ? "—" : n.toFixed(digits) + unit}</div></div>`; };
    const stats = [stat(c.charged_today, "Chargé aujourd'hui", " kWh", 1), stat(c.discharged_today, "Déchargé aujourd'hui", " kWh", 1),
      stat(c.temperature, "Température", " °C", 0), stat(c.health, "Santé", " %", 0), stat(c.cycles, "Cycles", "", 0)].filter(Boolean).join("");
    const m = c.mode && this.st(c.mode);
    const modes = m && (m.attributes.options || []).length ? `<div class="modes"><div class="lbl">${this.t("Mode")}</div><div class="seg">${m.attributes.options.map((o) =>
      `<span class="btn ${m.state === o ? "on" : ""}" ${this.call(`${c.mode.split(".")[0]}.select_option`, { entity_id: c.mode, option: o })}>${this.esc(o)}</span>`).join("")}</div></div>` : "";
    return this.frame(this.esc(c.title || this.t("Batterie")), soc === null ? "" : `${Math.round(soc)} %`, `
      <div class="gauge"><div class="ring click" data-e="${c.soc || c.power}"><svg viewBox="0 0 132 132"><circle cx="66" cy="66" r="${R}" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="9"/>
          <circle cx="66" cy="66" r="${R}" fill="none" stroke="${col}" stroke-width="9" stroke-linecap="round" stroke-dasharray="${(C * pct) / 100} ${C}" style="filter:drop-shadow(0 0 5px ${col})"/></svg>
          <div class="t"><b>${soc === null ? "—" : Math.round(soc)}<span style="font-size:14px">%</span></b><small>${this.t("NIVEAU")}</small></div></div>
        <div><div class="st" style="color:${idle ? SF_C.dim : bw > 0 ? SF_C.amber : SF_C.green}">${this.icon(idle ? "mdi:battery-heart-variant" : bw > 0 ? "mdi:battery-arrow-down" : "mdi:battery-arrow-up", 20)} ${state}</div>
          <div class="sub">${bw === null ? "" : this.kw(Math.abs(bw))}${eta ? `<br>${eta}` : ""}</div></div></div>
      ${stats ? `<div class="stats">${stats}</div>` : ""}${modes}`);
  }
  getCardSize() { return 4; }
}

/* ============================================================ RADIATEURS */
/*
 * Radiateurs pilotés par préréglage (Voltalis, Tado, Netatmo…) qui n'ont pas toujours de sonde de
 * température : état de chauffe, préréglage (une pastille par mode proposé par l'appareil),
 * consigne ± et consommation du jour. Pensé pour le téléphone (une colonne, grandes cibles).
 *
 * type: custom:sf-radiators-card
 * title: Radiateurs        accent: "#e07a4f"     step: 0.5     max_kwh: 5
 * setpoint: false          # fil pilote : pas de consigne chiffrée, on masque le réglage ±
 * preset_labels: { away: "Hors-gel" }   # renomme un préréglage
 * radiators:
 *   - { name, icon, climate: climate.x, kwh: sensor.x (consommation du jour), connection: sensor.x (facultatif),
 *       preset: select.x (facultatif : liste de préréglages d'un select, ex. avec « auto »), presets: [auto, comfort, eco, away] (ordre / filtre) }
 */
const SF_PRESETS = { auto: "Programme", comfort: "Confort", eco: "Éco", away: "Absent", none: "Aucun", boost: "Boost", sleep: "Nuit", home: "Présent", activity: "Activité", frost_protection: "Hors-gel" };
class SfRadiatorsCard extends SfBase {
  defaults() { return { radiators: [], step: 0.5, max_kwh: 5, setpoint: true, preset_labels: {} }; }
  css() {
    const ac = this._config.accent || SF_C.amber;
    return `
      .hud { --ac:${ac}; }
      .head, .hud .c { color:var(--ac); border-color:var(--ac); text-shadow:0 0 8px color-mix(in srgb, var(--ac) 60%, transparent); }
      .dot { background:var(--ac); box-shadow:0 0 8px var(--ac); }
      .list { display:grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr)); gap:10px; }
      .rad { padding:11px 12px 12px; border-radius:12px; background:rgba(255,255,255,.03);
        border:1px solid color-mix(in srgb, var(--ac) 22%, transparent); }
      .rad.heat { border-color:color-mix(in srgb, var(--ac) 70%, transparent); background:color-mix(in srgb, var(--ac) 9%, transparent);
        box-shadow:0 0 16px -6px var(--ac); }
      .rad.off { opacity:.6; }
      .rh { display:flex; align-items:center; gap:8px; }
      .rh .nm { flex:1; min-width:0; font-weight:700; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:#fff; }
      .rh .st { font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:${SF_C.dim}; }
      .rad.heat .rh .st { color:var(--ac); }
      .rad.heat .rh ha-icon { animation: rglow 2.2s ease-in-out infinite; }
      @keyframes rglow { 50% { filter:drop-shadow(0 0 5px var(--ac)); } }
      .pw { min-width:40px; min-height:36px; }
      .pw.on { border-color:var(--ac); background:color-mix(in srgb, var(--ac) 22%, transparent); box-shadow: inset 0 0 12px color-mix(in srgb, var(--ac) 30%, transparent); }
      .presets { display:grid; grid-template-columns: repeat(auto-fit, minmax(64px, 1fr)); gap:6px; margin-top:10px; }
      .presets .btn { min-height:38px; padding:6px 4px; }
      .presets .btn.on { border-color:var(--ac); background:color-mix(in srgb, var(--ac) 22%, transparent); box-shadow: inset 0 0 12px color-mix(in srgb, var(--ac) 30%, transparent); }
      .ctl { display:flex; align-items:center; justify-content:center; gap:10px; margin-top:10px; }
      .ctl .btn { min-width:44px; min-height:40px; font-size:16px; }
      .ctl .tg { text-align:center; min-width:96px; }
      .ctl .tg small { display:block; font-size:9px; letter-spacing:.14em; color:${SF_C.dim}; }
      .ctl .tg b { font-family:Orbitron,sans-serif; font-size:20px; color:#fff; text-shadow:0 0 10px var(--ac); }
      .meta { display:flex; align-items:center; gap:8px; margin-top:10px; font-size:10px; color:${SF_C.dim}; }
      .meta .bar { flex:1; height:4px; border-radius:2px; background:rgba(255,255,255,.07); overflow:hidden; }
      .meta .bar i { display:block; height:100%; background:var(--ac); box-shadow:0 0 6px var(--ac); border-radius:2px; transition:width 1s; }
      .warn { color:${SF_C.amber}; }`;
  }
  _label(p) { const l = (this._config.preset_labels || {})[p]; return l ? this.esc(l) : SF_PRESETS[p] ? this.t(SF_PRESETS[p]) : this.esc(p); }
  _rad(r) {
    const c = this._config, cl = this.st(r.climate), dead = !cl || cl.state === "unavailable";
    const a = (cl && cl.attributes) || {};
    const mode = cl ? cl.state : "unavailable", off = mode === "off";
    const heat = !dead && !off && a.hvac_action === "heating";
    // Préréglages : ceux d'un `select` si fourni (il propose souvent « auto » en plus), sinon ceux du climate.
    const sel = r.preset && this.st(r.preset), viaSel = !!(sel && sel.state !== "unavailable");
    let presets = viaSel ? (sel.attributes.options || []) : (a.preset_modes || []);
    if (r.presets) presets = r.presets.filter((p) => presets.includes(p));
    else if (viaSel) presets = presets.filter((p) => p !== "temperature");
    const cur = viaSel ? sel.state : a.preset_mode;
    const tgt = typeof a.temperature === "number" ? a.temperature : null;
    const now = typeof a.current_temperature === "number" ? a.current_temperature : null;
    const step = Number(c.step) || 0.5, lo = a.min_temp ?? 5, hi = a.max_temp ?? 30;
    const setT = (d) => this.call("climate.set_temperature", { entity_id: r.climate, temperature: Math.round(Math.max(lo, Math.min(hi, tgt + d * step)) * 10) / 10 });
    const kwh = r.kwh ? this.num(r.kwh) : null;
    const u = r.kwh ? this.unit(r.kwh).toLowerCase() : "";
    const kv = kwh === null ? null : (u === "wh" ? kwh / 1000 : kwh);
    const lost = r.connection && this.st(r.connection) && !["ok", "on", "connected", "online", "home"].includes(String(this.st(r.connection).state).toLowerCase());
    const status = dead ? this.t("Hors ligne") : off ? this.t("Éteint") : heat ? this.t("Chauffe") : this.t("En veille");
    return `<div class="rad ${heat ? "heat" : ""} ${off || dead ? "off" : ""}">
      <div class="rh">${this.icon(r.icon || "mdi:radiator", 20, heat ? "var(--ac)" : SF_C.dim)}
        <span class="nm click" data-e="${r.climate}">${this.esc(r.name)}</span>
        ${lost ? `<span class="warn click" data-e="${r.connection}" title="${this.t("connexion perdue")}">${this.icon("mdi:wifi-alert", 16, SF_C.amber)}</span>` : ""}
        <span class="st">${status}${now !== null ? ` · ${now.toFixed(1)}°` : ""}</span>
        ${dead ? "" : `<span class="btn pw ${off ? "" : "on"}" title="${this.t("allumer / éteindre le radiateur")}" ${this.call(off ? "climate.turn_on" : "climate.turn_off", { entity_id: r.climate })}>${this.icon("mdi:power", 16)}</span>`}</div>
      ${presets.length && !dead ? `<div class="presets">${presets.map((p) =>
        `<span class="btn ${cur === p && !off ? "on" : ""}" ${viaSel ? this.call("select.select_option", { entity_id: r.preset, option: p }) : this.call("climate.set_preset_mode", { entity_id: r.climate, preset_mode: p })}>${this._label(p)}</span>`).join("")}</div>` : ""}
      ${c.setpoint !== false && tgt !== null && !dead ? `<div class="ctl"><span class="btn" ${setT(-1)}>−</span>
        <div class="tg click" data-e="${r.climate}"><small>${this.t("CONSIGNE")}</small><b>${tgt.toFixed(1)}°</b></div>
        <span class="btn" ${setT(1)}>+</span></div>` : ""}
      ${kv !== null ? `<div class="meta"><span>${this.icon("mdi:flash", 12)} ${this.t("{k} kWh aujourd'hui", { k: kv.toFixed(2) })}</span>
        <span class="bar"><i style="width:${Math.min(100, (kv / (Number(c.max_kwh) || 5)) * 100)}%"></i></span></div>` : ""}</div>`;
  }
  render() {
    const c = this._config, rs = c.radiators || [];
    const n = rs.filter((r) => { const s = this.st(r.climate); return s && s.attributes.hvac_action === "heating" && s.state !== "off"; }).length;
    const tot = rs.reduce((t, r) => { const v = r.kwh ? this.num(r.kwh) : null; return t + (v === null ? 0 : (this.unit(r.kwh).toLowerCase() === "wh" ? v / 1000 : v)); }, 0);
    return this.frame(this.esc(c.title || this.t("Radiateurs")),
      `${this.t("{n} en chauffe", { n })} · ${tot.toFixed(1)} kWh`, `<div class="list">${rs.map((r) => this._rad(r)).join("")}</div>`);
  }
  getCardSize() { return 2 + (this._config.radiators || []).length * 2; }
}

