/* ============================================================ ÉDITEURS VISUELS */
/*
 * Chaque carte SF s'édite dans l'interface (« Modifier la carte ») sans écrire de YAML :
 * un formulaire HA (ha-form : sélecteurs d'entités, icônes, interrupteurs…) pour les réglages
 * simples, et des listes « + Ajouter / ↑ ↓ / Supprimer » pour les pièces, groupes, éléments, tuiles.
 * Les champs rares ou imbriqués (données d'un service, carte d'un panneau…) restent éditables
 * via un champ YAML intégré au formulaire. Un champ inconnu du formulaire n'est jamais perdu :
 * l'éditeur modifie la config en place et ne supprime que les valeurs vidées par l'utilisateur.
 */
const SF_ED_CSS = `
  :host { display:block; }
  h3 { margin:18px 0 6px; font-size:14px; font-weight:600; color:var(--primary-text-color); }
  h3:first-child { margin-top:4px; }
  .hint { font-size:12px; color:var(--secondary-text-color); margin:0 0 8px; }
  details { border:1px solid var(--divider-color); border-radius:10px; margin:0 0 8px; background:var(--card-background-color); }
  details > summary { display:flex; align-items:center; gap:6px; padding:8px 10px; cursor:pointer; list-style:none; font-weight:500; }
  details > summary::-webkit-details-marker { display:none; }
  details > summary::before { content:"▸"; color:var(--secondary-text-color); }
  details[open] > summary::before { content:"▾"; }
  summary .t { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .body { padding:4px 10px 10px; }
  .sub { margin-left:4px; padding-left:8px; border-left:2px solid var(--divider-color); }
  button { font:inherit; cursor:pointer; border:1px solid var(--divider-color); background:transparent;
    color:var(--primary-text-color); border-radius:8px; padding:3px 9px; }
  button:hover { border-color:var(--primary-color); }
  button.del.armed { background:var(--error-color); color:#fff; border-color:var(--error-color); }
  button.add { width:100%; padding:8px; border-style:dashed; color:var(--primary-color); }
`;

// Charge les composants de formulaire de HA (chargés à la demande par le frontend).
let _sfFormReady;
function sfLoadHaForm() {
  if (!_sfFormReady) _sfFormReady = (async () => {
    try {
      if (customElements.get("ha-form") && customElements.get("ha-entity-picker")) return;
      const h = await window.loadCardHelpers();
      const c = await h.createCardElement({ type: "entities", entities: [] });
      await c.constructor.getConfigElement();
    } catch (e) { /* le formulaire s'affichera dès que HA aura chargé ses composants */ }
  })();
  return _sfFormReady;
}

const sfE = (name, domain, extra) => ({ name, selector: { entity: { ...(domain ? { domain } : {}), ...(extra || {}) } } });
const sfEs = (name, domain) => sfE(name, domain, { multiple: true });
const sfT = (name) => ({ name, selector: { text: {} } });
const sfI = (name) => ({ name, selector: { icon: {} } });
const sfN = (name, min, max, step) => ({ name, selector: { number: { min, max, step: step ?? 1, mode: "box" } } });
const sfB = (name) => ({ name, selector: { boolean: {} } });
const sfS = (name, opts) => ({ name, selector: { select: { mode: "dropdown", options: opts.map(([value, label]) => ({ value, label })) } } });
const sfO = (name) => ({ name, selector: { object: {} } });
const sfG = (...schema) => ({ type: "grid", name: "", schema });

const SF_LABELS = {
  name: "Nom", label: "Libellé", icon: "Icône", color: "Couleur (ex. #00e5ff)", title: "Titre", subtitle: "Sous-titre",
  entity: "Entité", sub: "Texte sous le titre", unit: "Unité", digits: "Décimales", warn: "Seuil d'alerte (orange)",
  crit: "Seuil critique (rouge)", max: "Valeur maximale", min: "Minimum", timer: "Minuteur (affiche le temps restant)",
  stop: "Entités coupées par un appui pendant le minuteur", hash: "Lien du panneau (#…)", columns: "Colonnes",
};

const SF_KINDS = [["toggle", "Interrupteur / lumière"], ["dimmer", "Lampe avec variation"], ["action", "Bouton d'action (service)"],
  ["sensor", "Valeur à afficher"], ["cover", "Volets"], ["vacuum", "Aspirateur"], ["stepper", "Réglage + / −"], ["select", "Choix dans une liste"]];

function sfConsoleItem(it) {
  const k = it.kind || "toggle";
  const dom = { toggle: ["light", "switch", "fan", "input_boolean", "automation"], dimmer: "light", cover: "cover", vacuum: "vacuum",
    stepper: ["input_number", "number"], select: ["input_select", "select"] }[k];
  const s = [sfS("kind", SF_KINDS), sfT("label")];
  if (k === "action") s.push(sfG(sfI("icon"), sfT("color")), sfT("sub"), sfT("service"), sfT("confirm"), sfO("data"));
  else {
    s.push(sfE("entity", dom));
    if (["toggle", "sensor", "stepper"].includes(k)) s.push(sfI("icon"));
    if (k === "toggle" || k === "dimmer") s.push(sfT("color"));
    if (k === "sensor" || k === "stepper") s.push(sfG(sfT("unit"), sfN("digits", 0, 4)));
    if (k === "vacuum") s.push(sfE("battery", "sensor"), sfO("shortcuts"));
  }
  return s;
}

const SF_TILE_KINDS = [["value", "Valeur (avec seuils)"], ["percent", "Pourcentage"], ["binary", "Oui / non"], ["text", "Texte"],
  ["duration", "Durée"], ["timestamp", "Date / heure"], ["toggle", "Bouton marche / arrêt"]];
function sfMachineTile(t) {
  const k = t.kind || "value";
  const s = [sfT("label"), sfE("entity"), sfS("kind", SF_TILE_KINDS)];
  if (k === "value") s.push(sfG(sfT("unit"), sfN("digits", 0, 4)), sfG(sfN("warn"), sfN("crit")), sfG(sfN("low"), sfN("max")), sfB("invert"));
  if (k === "percent") s.push(sfG(sfN("warn", 0, 100), sfN("crit", 0, 100)));
  if (k === "binary") s.push(sfT("ok_state"), sfT("bad_text"));
  if (k === "text") s.push(sfO("map"), sfO("ok_values"));
  if (k === "duration") s.push(sfG(sfN("warn"), sfN("max")));
  if (k === "toggle") s.push(sfT("color"), sfE("timer", "timer"), sfEs("stop"));
  return s;
}

